DO $$
BEGIN
  IF (SELECT count(*) FROM assignments WHERE course_code = ANY(ARRAY['SCH4U', 'ICS4U', 'SPH4U', 'MHF4U', 'MCV4U', 'BBB4M']::text[]) AND module_id IS NOT NULL) <> 38 THEN
    RAISE EXCEPTION 'Catalog seed assertion failed: expected 38 assignments';
  END IF;
END $$;

DO $$
DECLARE
  scoped_courses text[] := ARRAY['SCH4U', 'ICS4U', 'SPH4U', 'MHF4U', 'MCV4U', 'BBB4M']::text[];
BEGIN
  IF (SELECT count(*) FROM course_modules WHERE course_code = ANY(scoped_courses)) <> 72 THEN
    RAISE EXCEPTION 'Catalog seed assertion failed: expected 72 modules';
  END IF;
  IF (SELECT count(*) FROM module_lessons l JOIN course_modules m ON m.id = l.module_id WHERE m.course_code = ANY(scoped_courses)) <> 120 THEN
    RAISE EXCEPTION 'Catalog seed assertion failed: expected 120 lessons';
  END IF;
  IF (SELECT count(*) FROM module_resources r JOIN course_modules m ON m.id = r.module_id WHERE m.course_code = ANY(scoped_courses)) <> 198 THEN
    RAISE EXCEPTION 'Catalog seed assertion failed: expected 198 resources';
  END IF;
  IF (SELECT count(*) FROM module_activities a JOIN course_modules m ON m.id = a.module_id WHERE m.course_code = ANY(scoped_courses)) <> 72 THEN
    RAISE EXCEPTION 'Catalog seed assertion failed: expected 72 activities';
  END IF;
  IF (SELECT count(*) FROM gradebook_items WHERE course_code = ANY(scoped_courses)) <> 44 THEN
    RAISE EXCEPTION 'Catalog seed assertion failed: expected 44 gradebook items';
  END IF;
  IF (SELECT count(*) FROM assessment_components c JOIN module_activities a ON a.id = c.module_activity_id JOIN course_modules m ON m.id = a.module_id WHERE m.course_code = ANY(scoped_courses)) <> 38 THEN
    RAISE EXCEPTION 'Catalog seed assertion failed: expected 38 assessment components';
  END IF;
  IF EXISTS (
    SELECT course_code
    FROM course_modules
    WHERE course_code = ANY(scoped_courses)
    GROUP BY course_code
    HAVING count(*) <> 12 OR sum(estimated_credit_hours) <> 110
  ) THEN
    RAISE EXCEPTION 'Catalog seed assertion failed: every course must have 12 modules and 110 hours';
  END IF;
  IF EXISTS (
    SELECT course_code
    FROM gradebook_items
    WHERE course_code = ANY(scoped_courses)
    GROUP BY course_code
    HAVING sum(weight_percent) <> 100
  ) THEN
    RAISE EXCEPTION 'Catalog seed assertion failed: every gradebook must total 100 percent';
  END IF;
END $$;

VALUES ('lotus-grade12-six-course-v1', 'd6a78226ac740ff5a6e8d0569762856db1110e8599175613f41567d9fbc915d8', 6, 72, 120, 198)
