INSERT INTO courses (code, title, status) VALUES
  ('SCH4U', 'Chemistry', 'active'),
  ('ICS4U', 'Computer Science', 'active'),
  ('SPH4U', 'Physics', 'active'),
  ('MHF4U', 'Advanced Functions', 'active'),
  ('MCV4U', 'Calculus and Vectors', 'active'),
  ('BBB4M', 'International Business Fundamentals', 'active')
INSERT INTO course_modules (id, course_code, module_number, unit_number, title, unit_title, learning_focus, core_reading_order, guided_practice, low_stakes_check, feedback_and_unlock, estimated_credit_hours, workload_label, teacher_presence, evidence_to_retain, status) VALUES
  ('sch4u-m00', 'SCH4U', 0, NULL, 'Start Here: Learning Chemistry in the Lotus Platform', 'Course Orientation', '["Navigate the course, locate feedback and due dates, and explain the approved grade structure: 65% coursework, 25% mandatory written examination, 10% attendance and participation.","Establish safe, ethical, and traceable practices for data, calculations, citations, and virtual investigations."]'::jsonb, '["Read the course welcome, navigation guide, communication routines, and accessibility/support information.","Read the assessment overview, academic-integrity expectations, scientific-source rules, and safety boundaries.","Preview the five unit assessments and the SCH4U Mandatory Written Examination before beginning content."]'::jsonb, 'Complete a navigation scavenger hunt, submit a sample equation-and-source record, and practise finding rubric feedback.', 'Ungraded prerequisite diagnostic covering Grade 11 chemistry, algebra, units, significant figures, and interpretation of tables/graphs; students receive a targeted review list.', 'Teacher or automated feedback identifies prerequisite gaps. Unlock Module 1 after the navigation check and acknowledgement are complete; diagnostic score does not restrict entry.', 0, '1–2 h onboarding; not automatically recorded as credit time', 'Welcome message, diagnostic response, support routing, and navigation confirmation.', 'Navigation check, diagnostic record, and safety/integrity acknowledgement.', 'published'),
  ('sch4u-m01', 'SCH4U', 1, 1, 'Organic Structures, Names, and Property Patterns', 'Organic Chemistry', '["Represent and name organic structures using a consistent decision process.","Use functional groups, molecular geometry, and intermolecular forces to predict properties."]'::jsonb, '["Student Coursebook Lesson SCH4U-U1-L1: Carbon Skeletons, Functional Groups, and Systematic Names.","Complete the nomenclature retrieval set and correct every locant, parent-chain, and suffix error.","Student Coursebook Lesson SCH4U-U1-L2: Intermolecular Forces and Organic Physical Properties.","Complete the structure-property comparison before opening the extension resources."]'::jsonb, 'Build a functional-group identification deck, complete bidirectional name-to-structure practice, and defend a boiling-point or solubility ranking with geometry and intermolecular-force evidence.', 'Ten-item nomenclature and structure-property check with one correction attempt; add each error to the course correction log.', 'Unlock Module 2 after both lesson checkpoints and a correction entry are submitted. Teacher feedback targets nomenclature logic and evidence quality, not only the final answer.', 8, '8 h core lessons and embedded checks', 'Targeted response to the retrieval check or correction log, plus a discussion, office-hour, or message touchpoint.', 'Annotated readings, guided practice, knowledge-check corrections, and exit ticket.', 'published'),
  ('sch4u-m02', 'SCH4U', 2, 1, 'Organic Reactions, Polymers, and Safer Product Decisions', 'Organic Chemistry', '["Classify organic transformations and distinguish an overall reaction from a supported pathway.","Evaluate performance, hazard, exposure, and life-cycle evidence in a product decision."]'::jsonb, '["Student Coursebook Lesson SCH4U-U1-L3: Organic Reaction Families and Evidence-Based Pathways.","Complete a reaction-family map and balance the assigned transformation.","Student Coursebook Lesson SCH4U-U1-L4: Polymers, Petrochemicals, and Life-Cycle Decisions.","Assessment Reading Library: Evidence File 1: Solvent Reformulation for a Coating Process.","Annotate the assessment brief and rubric before drafting the product comparison."]'::jsonb, 'Complete a reaction-pathway evidence table and a four-criterion safer-solvent decision matrix, then submit a one-paragraph conditional recommendation for feedback.', 'Assessment-readiness quiz on reaction families, polymer structure, hazard versus exposure, and life-cycle trade-offs, followed by a rubric self-check.', 'Teacher gives rubric-linked feedback at the claim/calculation checkpoint. Unlock Module 3 after final submission and a brief reflection identifying one evidence limitation.', 14, '14 h lessons, application, assessment, and feedback', 'Rubric-linked process feedback, an authentication checkpoint or conference, and a documented unlock decision.', 'Evidence-file notes, staged assessment work, feedback record, final submission, and reflection or defence.', 'published'),
  ('sch4u-m03', 'SCH4U', 3, 2, 'Atomic Evidence and Bond Models', 'Structure and Properties of Matter', '["Use electron configurations and periodic evidence to explain trends.","Construct and evaluate Lewis, formal-charge, resonance, and bonding representations."]'::jsonb, '["Student Coursebook Lesson SCH4U-U2-L1: Quantum Model, Electron Configurations, and Periodic Evidence.","Complete the electron-configuration and periodic-trend retrieval set.","Student Coursebook Lesson SCH4U-U2-L2: Lewis Structures, Formal Charge, Resonance, and Bond Models.","Complete a representation-choice comparison before using the simulation/database resources."]'::jsonb, 'Complete an electron-configuration error sort, select the most defensible Lewis/resonance representation for assigned species, and explain where each model is useful or limited.', 'Mixed short-answer check on configurations, trends, bond type, formal charge, and resonance; require an annotated correction for every missed item.', 'Unlock Module 4 after students submit one complete model comparison and correct the readiness check. Teacher flags persistent charge-counting or periodic-trend misconceptions.', 8, '8 h core lessons and embedded checks', 'Targeted response to the retrieval check or correction log, plus a discussion, office-hour, or message touchpoint.', 'Annotated readings, guided practice, knowledge-check corrections, and exit ticket.', 'published'),
  ('sch4u-m04', 'SCH4U', 4, 2, 'Molecular Geometry and Material Selection', 'Structure and Properties of Matter', '["Connect geometry, hybridization, polarity, and spectra to molecular evidence.","Infer bonding/solid structure from a bounded set of material properties and justify a technology choice."]'::jsonb, '["Student Coursebook Lesson SCH4U-U2-L3: Molecular Geometry, Hybridization, Polarity, and Spectral Evidence.","Complete a predict-build-explain geometry table.","Student Coursebook Lesson SCH4U-U2-L4: Solids, Materials, and Technology Decisions.","Assessment Reading Library: Evidence File 2: Selecting a Material for a High-Temperature Sensor Housing.","Annotate the coded-material evidence and rejection criteria before drafting."]'::jsonb, 'Classify four anonymous materials from partial property sets, identify the next most useful test, and write a claim-evidence-reasoning rejection of one plausible alternative.', 'Geometry/polarity/solid-type readiness quiz plus a one-page evidence sufficiency checklist.', 'Teacher checks the chain from data to model to recommendation before final submission. Unlock Module 5 after the assessment and an uncertainty statement are submitted.', 14, '14 h lessons, application, assessment, and feedback', 'Rubric-linked process feedback, an authentication checkpoint or conference, and a documented unlock decision.', 'Evidence-file notes, staged assessment work, feedback record, final submission, and reflection or defence.', 'published'),
  ('sch4u-m05', 'SCH4U', 5, 3, 'Enthalpy, Calorimetry, and Energy Pathways', 'Energy Changes and Rates of Reaction', '["Define systems consistently and calculate energy changes from calorimetry evidence.","Use Hess''s law, formation enthalpies, and energy profiles while tracking signs and assumptions."]'::jsonb, '["Student Coursebook Lesson SCH4U-U3-L1: Systems, Enthalpy, Calorimetry, and Measurement Quality.","Complete the sign-convention and calorimetry worked-example set.","Student Coursebook Lesson SCH4U-U3-L2: Hess''s Law, Formation Enthalpies, and Energy Profiles.","Complete one pathway calculation in two independent ways and reconcile any mismatch."]'::jsonb, 'Audit a flawed calorimetry solution, complete a Hess-cycle card sort, and compare pathway-independent enthalpy with an activation-energy profile.', 'Short calculation set requiring equations, units, sign convention, assumptions, and one uncertainty comment; students resubmit corrected work.', 'Unlock Module 6 after a fully annotated Hess/calorimetry solution is accepted. Teacher feedback prioritizes system boundaries, signs, and evidence quality.', 8, '8 h core lessons and embedded checks', 'Targeted response to the retrieval check or correction log, plus a discussion, office-hour, or message touchpoint.', 'Annotated readings, guided practice, knowledge-check corrections, and exit ticket.', 'published'),
  ('sch4u-m06', 'SCH4U', 6, 3, 'Rates, Mechanisms, and Process Optimization', 'Energy Changes and Rates of Reaction', '["Infer rate relationships from controlled data and distinguish rate, rate constant, and reaction order.","Evaluate mechanisms, catalysts, operating conditions, safety, energy, and emissions in a process decision."]'::jsonb, '["Student Coursebook Lesson SCH4U-U3-L3: Reaction Rates, Rate Laws, and Data Interpretation.","Complete the initial-rate and temperature-data practice.","Student Coursebook Lesson SCH4U-U3-L4: Mechanisms, Catalysis, and Responsible Process Design.","Assessment Reading Library: Evidence File 3: Choosing Conditions for a Catalysed Production Route.","Annotate the evidence file for comparable basis, constraints, and uncertainty before optimization."]'::jsonb, 'Determine rate-law evidence from controlled trials, reject an unsupported mechanism, and use a normalized decision matrix to compare two process routes.', 'Readiness check on orders, units, mechanisms, catalyst claims, normalization, and sensitivity; students complete a rubric-based preflight.', 'Teacher checks data comparability and one sensitivity calculation before final submission. Unlock Module 7 after assessment submission and documented revision decisions.', 14, '14 h lessons, application, assessment, and feedback', 'Rubric-linked process feedback, an authentication checkpoint or conference, and a documented unlock decision.', 'Evidence-file notes, staged assessment work, feedback record, final submission, and reflection or defence.', 'published'),
  ('sch4u-m07', 'SCH4U', 7, 4, 'Dynamic Equilibrium and Quantitative System Models', 'Chemical Systems and Equilibrium', '["Use particle and symbolic models to distinguish equilibrium rate, position, K, and Q.","Solve bounded equilibrium systems with ICE tables and evaluate qualitative shift claims."]'::jsonb, '["Student Coursebook Lesson SCH4U-U4-L1: Dynamic Equilibrium, K, and Reaction Quotient.","Complete a Q-versus-K prediction set before viewing solutions.","Student Coursebook Lesson SCH4U-U4-L2: ICE Tables, Le Châtelier Reasoning, and Coupled Systems.","Complete one ICE-table solution with a verification substitution."]'::jsonb, 'Sort equilibrium claims into rate, position, K, or Q; complete two ICE tables; and diagnose a Le Châtelier shortcut that conflicts with the equilibrium expression.', 'Mixed conceptual/calculation check with a required verification step and a particle-level explanation.', 'Unlock Module 8 after the verified ICE-table solution and correction log are complete. Teacher feedback identifies when a verbal shift claim is not supported by K/Q mathematics.', 8, '8 h core lessons and embedded checks', 'Targeted response to the retrieval check or correction log, plus a discussion, office-hour, or message touchpoint.', 'Annotated readings, guided practice, knowledge-check corrections, and exit ticket.', 'published'),
  ('sch4u-m08', 'SCH4U', 8, 4, 'Acid-Base, Solubility, and Water-System Decisions', 'Chemical Systems and Equilibrium', '["Interpret acid-base, buffer, titration, and solubility evidence using appropriate equilibrium models.","Develop a conditional water-treatment recommendation that acknowledges coupled systems and uncertainty."]'::jsonb, '["Student Coursebook Lesson SCH4U-U4-L3: Acids, Bases, Buffers, and Titration Evidence.","Complete the acid-base and buffer calculation checkpoint.","Student Coursebook Lesson SCH4U-U4-L4: Solubility Equilibria, Water Systems, and Treatment Trade-offs.","Assessment Reading Library: Evidence File 4: Carbonate Balance and Distribution-System Decision.","Map gas dissolution, pH, buffering, Ksp, scaling, and corrosion before drafting."]'::jsonb, 'Complete a coupled carbonate-system map, solve one buffer and one Ksp case, then write a public-facing recommendation that separates findings, assumptions, and monitoring triggers.', 'Assessment-readiness check on pH, Ka/Kb, buffers, Qsp/Ksp, conditional language, and evidence traceability.', 'Teacher verifies one coupled calculation and the distinction between evidence and assumption. Unlock Module 9 after final submission and a documented monitoring/revision trigger.', 14, '14 h lessons, application, assessment, and feedback', 'Rubric-linked process feedback, an authentication checkpoint or conference, and a documented unlock decision.', 'Evidence-file notes, staged assessment work, feedback record, final submission, and reflection or defence.', 'published'),
  ('sch4u-m09', 'SCH4U', 9, 5, 'Redox Accounting and Galvanic Cells', 'Electrochemistry', '["Assign oxidation states and balance redox reactions in appropriate media.","Represent galvanic cells and use standard potentials to interpret spontaneity and energy conversion."]'::jsonb, '["Student Coursebook Lesson SCH4U-U5-L1: Oxidation Numbers and Balancing Redox Reactions.","Complete the oxidation-number and half-reaction balancing set.","Student Coursebook Lesson SCH4U-U5-L2: Galvanic Cells, Standard Potentials, and Thermodynamic Meaning.","Complete a labelled cell diagram and verify the calculated cell potential."]'::jsonb, 'Balance redox reactions, build cell-notation/diagram translations, calculate E°cell, and explain why a positive standard potential does not by itself determine real-world battery suitability.', 'Redox and galvanic-cell check requiring direction labels, units, sign logic, and one thermodynamic interpretation.', 'Unlock Module 10 after one correct cell representation and an annotated correction are submitted. Teacher feedback targets anode/cathode conventions and sign reasoning.', 8, '8 h core lessons and embedded checks', 'Targeted response to the retrieval check or correction log, plus a discussion, office-hour, or message touchpoint.', 'Annotated readings, guided practice, knowledge-check corrections, and exit ticket.', 'published'),
  ('sch4u-m10', 'SCH4U', 10, 5, 'Electrolysis, Batteries, Corrosion, and Lifecycle Control', 'Electrochemistry', '["Use Faraday''s law and efficiency evidence to analyse electrolysis and storage systems.","Compare performance, safety, corrosion control, service life, and end-of-life trade-offs."]'::jsonb, '["Student Coursebook Lesson SCH4U-U5-L3: Electrolysis, Faraday''s Law, and Industrial Accounting.","Complete the charge-moles-mass calculation pathway and an efficiency check.","Student Coursebook Lesson SCH4U-U5-L4: Batteries, Fuel Cells, Corrosion, and Lifecycle Control.","Assessment Reading Library: Evidence File 5: Remote Clinic Energy Storage and Corrosion Plan.","Annotate operating constraints, safety thresholds, sensitivity variables, and end-of-life requirements."]'::jsonb, 'Complete an electrolysis accounting case, compare two storage/corrosion options on a normalized basis, and conduct one sensitivity test before writing the recommendation.', 'Assessment-readiness check on Faraday''s law, energy/capacity units, corrosion mechanisms, safety thresholds, lifecycle evidence, and conditional recommendations.', 'Teacher verifies the electrochemical accounting and one safety/lifecycle constraint before final submission. Unlock Module 11 after the assessment and feedback-use reflection are complete.', 11.5, '11.5 h lessons, application, assessment, and feedback', 'Rubric-linked process feedback, an authentication checkpoint or conference, and a documented unlock decision.', 'Evidence-file notes, staged assessment work, feedback record, final submission, and reflection or defence.', 'published'),
  ('sch4u-m11', 'SCH4U', 11, NULL, 'Cumulative Synthesis and Mandatory Written Examination', 'Final Evaluation', '["Integrate structure-property, energy-rate, equilibrium, and electrochemical reasoning across unfamiliar contexts.","Demonstrate independent, time-bounded problem solving and evidence communication."]'::jsonb, '["Review the five unit concept maps and correction logs; identify one persistent misconception per unit.","Complete an interleaved problem set that requires model selection before calculation.","Complete one timed practice examination, analyse errors by category, and attend the required feedback conference.","Read the examination instructions, permitted materials, integrity requirements, and submission procedure."]'::jsonb, 'Use a five-station spiral review: identify the governing model, solve, check units/limits, explain evidence, and revise. Finish with a timed mock and a teacher conference based on the error log.', 'Exam-readiness checklist and timed mock examination; mock score is formative and does not replace the mandatory written examination.', 'The examination opens only after required coursework submissions and the exam-integrity check are complete, subject to documented accommodations. Final teacher feedback distinguishes content, model-selection, calculation, and communication errors.', 2.5, '2.5 h supervised written examination', 'Readiness confirmation, approved accommodations, identity check, supervision, and post-exam closure.', 'Supervised examination script and administration record.', 'published'),
  ('ics4u-m00', 'ICS4U', 0, NULL, 'Start Here: Learning Computer Science in the Lotus Platform', 'Course Orientation', '["Navigate the course, locate feedback and due dates, and explain the approved grade structure: 65% coursework, 10% culminating performance and defence, 15% mandatory written examination, 10% attendance and participation.","Establish safe, ethical, accessible, and traceable practices for local programming, fictional data, citations, version evidence, and technical support."]'::jsonb, '["Read the course welcome, navigation guide, communication routines, and accessibility/support information.","Read the assessment overview, academic-integrity expectations, source-and-licence rules, and the boundaries for local, authorized computing work.","Preview the five unit assessments and the ICS4U Mandatory Written Examination before beginning content.","Preview ICS4U Culminating Performance and Defence and its staged authenticated defence checkpoints."]'::jsonb, 'Complete a navigation scavenger hunt, submit a harmless local code-and-source record using fictional data, and practise finding rubric and code-review feedback.', 'Ungraded prerequisite diagnostic covering Grade 11 programming, variables, selection, iteration, functions, basic collections, tracing, and test cases; students receive a targeted review list.', 'Teacher or automated feedback identifies prerequisite gaps. Unlock Module 1 after the navigation check and acknowledgement are complete; diagnostic score does not restrict entry.', 0, '1–2 h onboarding; not automatically recorded as credit time', 'Welcome message, diagnostic response, support routing, and navigation confirmation.', 'Navigation check, diagnostic record, and safety/integrity acknowledgement.', 'published'),
  ('ics4u-m01', 'ICS4U', 1, 1, 'Traceable State, Collections, and Iterative Reasoning', 'Programming Concepts and Skills', '["Choose data types and expressions that make program state and correctness conditions visible.","Trace collection, iteration, and accumulation patterns across normal, boundary, and empty inputs."]'::jsonb, '["Student Coursebook Lesson ICS4U-U1-L1: Data Types, Expressions, and Traceable State.","Complete the variable-state trace and identify one type or expression error before running code.","Student Coursebook Lesson ICS4U-U1-L2: Collections, Iteration, and Accumulation Patterns.","Complete the loop-invariant and empty-collection check before opening the external practice resources."]'::jsonb, 'Trace three short programs, repair a type mismatch, and implement a collection summary that correctly handles empty, single-item, and repeated-value cases.', 'Ten-item code-trace and collection-pattern check with one correction attempt; record each misconception and the test that exposes it.', 'Unlock Module 2 after both lesson checkpoints and one corrected trace are submitted. Teacher feedback targets reasoning about state and invariants, not only final output.', 8, '8 h core lessons and embedded checks', 'Targeted response to the retrieval check or correction log, plus a discussion, office-hour, or message touchpoint.', 'Annotated readings, guided practice, knowledge-check corrections, and exit ticket.', 'published'),
  ('ics4u-m02', 'ICS4U', 2, 1, 'Structured Records, Function Contracts, and Data Quality', 'Programming Concepts and Skills', '["Parse strings, local files, and structured records without losing the distinction between missing, malformed, and valid values.","Design focused functions with explicit contracts and test evidence that makes defects reproducible."]'::jsonb, '["Student Coursebook Lesson ICS4U-U1-L3: Strings, Local Files, and Structured Records.","Complete the fictional record-parsing table and preserve each original input before normalization.","Student Coursebook Lesson ICS4U-U1-L4: Function Contracts, Testing, and Debugging.","Assessment Reading Library: Evidence File 1: Fictional Community-Asset Data Quality Case.","Annotate the assessment brief, function contracts, test expectations, and rubric before implementation."]'::jsonb, 'Build a data dictionary, separate parsing from validation and reporting, write normal/boundary/missing/malformed tests, and demonstrate one defect-and-repair cycle.', 'Assessment-readiness check on file handling, record validation, contracts, helpful error messages, and regression tests, followed by a rubric self-check.', 'Teacher gives contract- and test-linked feedback before final submission. Unlock Module 3 after final submission and a reflection identifying one defect, revision, and remaining limitation.', 14, '14 h lessons, application, assessment, and feedback', 'Rubric-linked process feedback, an authentication checkpoint or conference, and a documented unlock decision.', 'Evidence-file notes, staged assessment work, feedback record, final submission, and reflection or defence.', 'published'),
  ('ics4u-m03', 'ICS4U', 3, 2, 'Modular Boundaries, Interfaces, and Recursion', 'Software Development', '["Decompose a bounded problem into cohesive modules with explicit interfaces and manageable dependencies.","Trace recursive calls, justify a terminating base case, and compare recursive and iterative alternatives."]'::jsonb, '["Student Coursebook Lesson ICS4U-U2-L1: Decomposition, Interfaces, Cohesion, and Coupling.","Complete the module-responsibility and dependency map.","Student Coursebook Lesson ICS4U-U2-L2: Recursion, Base Cases, and Stack Reasoning.","Complete the call-stack trace and prove that the base case is reachable before running code."]'::jsonb, 'Partition a fictional rule engine into modules, identify two coupling problems, trace one recursive structure, and compare it with a loop using correctness, clarity, and memory criteria.', 'Interface-contract and recursion check requiring a responsibility table, stack trace, base-case explanation, and correction attempt.', 'Unlock Module 4 after the module map and corrected recursion trace are accepted. Teacher flags unclear contracts, cyclic dependencies, and non-terminating reasoning.', 8, '8 h core lessons and embedded checks', 'Targeted response to the retrieval check or correction log, plus a discussion, office-hour, or message touchpoint.', 'Annotated readings, guided practice, knowledge-check corrections, and exit ticket.', 'published'),
  ('ics4u-m04', 'ICS4U', 4, 2, 'Objects, Invariants, Exceptions, and Refactoring', 'Software Development', '["Use classes, encapsulation, composition, and invariants to prevent invalid program states.","Design safe error behaviour and use tests and documentation to verify behaviour-preserving refactoring."]'::jsonb, '["Student Coursebook Lesson ICS4U-U2-L3: Classes, Encapsulation, Composition, and Invariants.","Complete the object-state and invariant table.","Student Coursebook Lesson ICS4U-U2-L4: Exceptions, Documentation, and Behaviour-Preserving Refactoring.","Assessment Reading Library: Evidence File 2: Fictional Transit Fare Rule-Engine Architecture.","Annotate the architecture, recursion choice, invariant, error-behaviour, and refactoring evidence before designing the assessment library."]'::jsonb, 'Model valid and invalid task states, write public interface contracts, test modules independently, and complete a before-and-after refactor while preserving regression evidence.', 'Assessment-readiness quiz on composition, invariants, exception ownership, cohesion, coupling, independent tests, and accessible error states.', 'Teacher checks whether modules can change and be tested independently before integration. Unlock Module 5 after final submission and an explanation of one design trade-off.', 14, '14 h lessons, application, assessment, and feedback', 'Rubric-linked process feedback, an authentication checkpoint or conference, and a documented unlock decision.', 'Evidence-file notes, staged assessment work, feedback record, final submission, and reflection or defence.', 'published'),
  ('ics4u-m05', 'ICS4U', 5, 3, 'Correctness, Growth, and Search Strategies', 'Designing Modular Programs', '["Separate algorithm correctness from efficiency and relate input size to operation-count growth.","Choose linear, binary, or indexed lookup only when its preconditions and workload justify it."]'::jsonb, '["Student Coursebook Lesson ICS4U-U3-L1: Correctness, Input Size, and Asymptotic Growth.","Complete the operation-count table and state the correctness condition before comparing speed.","Student Coursebook Lesson ICS4U-U3-L2: Searching: Linear, Binary, and Indexed Lookup.","Trace each search strategy on found, absent, first, and last cases before using visual or textbook resources."]'::jsonb, 'Prove comparable outputs on generated data, count operations for growing input sizes, and recommend a search strategy for one small one-time query and one repeated large workload.', 'Mixed trace-and-explain check on correctness, preconditions, Big-O categories, preprocessing cost, and absent-key behaviour.', 'Unlock Module 6 after the correctness comparison and corrected search trace are submitted. Teacher feedback distinguishes unsupported speed claims from defensible complexity reasoning.', 8, '8 h core lessons and embedded checks', 'Targeted response to the retrieval check or correction log, plus a discussion, office-hour, or message touchpoint.', 'Annotated readings, guided practice, knowledge-check corrections, and exit ticket.', 'published'),
  ('ics4u-m06', 'ICS4U', 6, 3, 'Sorting, Data Structures, and Reproducible Benchmarks', 'Designing Modular Programs', '["Compare sorting strategies using correctness, stability, input pattern, time, and space rather than a single fastest run.","Select data structures from required semantics and design a reproducible local benchmark with stated limitations."]'::jsonb, '["Student Coursebook Lesson ICS4U-U3-L3: Sorting, Stability, and Comparison Trade-offs.","Complete hand traces on random, sorted, reverse, nearly sorted, and duplicate-heavy inputs.","Student Coursebook Lesson ICS4U-U3-L4: Data-Structure Selection and Reproducible Benchmarking.","Assessment Reading Library: Evidence File 3: Search, Sort, and Structure Benchmark Pack.","Annotate the correctness rule, generated input patterns, required operations, fair-comparison controls, and reporting template."]'::jsonb, 'Establish equal outputs, select generated datasets, repeat timed trials, report median and spread, and combine measured evidence with complexity and structure semantics in a conditional recommendation.', 'Assessment-readiness check on stability, fair variables, repeated trials, input patterns, data-structure semantics, and limitations, followed by a rubric self-audit.', 'Teacher checks correctness before timing and reviews reproducibility before the final recommendation. Unlock Module 7 after submission and a limitation statement.', 14, '14 h lessons, application, assessment, and feedback', 'Rubric-linked process feedback, an authentication checkpoint or conference, and a documented unlock decision.', 'Evidence-file notes, staged assessment work, feedback record, final submission, and reflection or defence.', 'published'),
  ('ics4u-m07', 'ICS4U', 7, 4, 'Requirements, Accessible Criteria, and Project Planning', 'Topics in Computer Science', '["Translate stakeholder needs into testable functional, non-functional, security, privacy, and accessibility criteria.","Plan a bounded project through a prioritized backlog, dependencies, milestones, risks, and traceable version evidence."]'::jsonb, '["Student Coursebook Lesson ICS4U-U4-L1: Requirements, User Stories, and Accessible Acceptance Criteria.","Complete a requirement-to-acceptance-test traceability table.","Student Coursebook Lesson ICS4U-U4-L2: Backlogs, Estimation, Dependencies, and Version Evidence.","Complete the backlog dependency map and identify the evidence required at each milestone."]'::jsonb, 'Draft a charter and scope boundary, write accessible user stories, prioritize a backlog, map dependencies, and link each milestone to a reviewable artifact and risk control.', 'Requirements-and-planning check requiring observable acceptance criteria, a dependency explanation, and a corrected traceability gap.', 'Unlock Module 8 after the charter, acceptance criteria, and first backlog pass review. Teacher feedback identifies ambiguous scope, inaccessible criteria, and unowned risks.', 8, '8 h core lessons and embedded checks', 'Targeted response to the retrieval check or correction log, plus a discussion, office-hour, or message touchpoint.', 'Annotated readings, guided practice, knowledge-check corrections, and exit ticket.', 'published'),
  ('ics4u-m08', 'ICS4U', 8, 4, 'Testing, Review, Licensing, and Project Closure', 'Topics in Computer Science', '["Design unit, integration, regression, acceptance, security, and accessibility evidence for a bounded local project.","Use review, documentation, licence records, release criteria, contribution evidence, and retrospectives to close work responsibly."]'::jsonb, '["Student Coursebook Lesson ICS4U-U4-L3: Test Strategy, Code Review, and Secure Local Development.","Complete the requirement-to-test matrix and one structured code review.","Student Coursebook Lesson ICS4U-U4-L4: Documentation, Licensing, Release Review, and Retrospective.","Assessment Reading Library: Evidence File 4: Fictional Project Governance and Quality Record.","Annotate the charter, backlog, risk register, defect, release conditions, contribution evidence, and retrospective prompts."]'::jsonb, 'Run a test-and-review cycle, repair an empty-state defect, update the guide and licence register, trace the change to a labelled version, and complete a no-blame process retrospective.', 'Assessment-readiness review of acceptance coverage, negative tests, accessibility, security, source/licence records, contribution evidence, and release criteria.', 'Teacher reviews team process and individual evidence separately. Unlock Module 9 after closing evidence, retrospective, and individual explanation are complete.', 14, '14 h lessons, application, assessment, and feedback', 'Rubric-linked process feedback, an authentication checkpoint or conference, and a documented unlock decision.', 'Evidence-file notes, staged assessment work, feedback record, final submission, and reflection or defence.', 'published'),
  ('ics4u-m09', 'ICS4U', 9, 5, 'Privacy, Bias, Accessibility, and Secure Design', 'Culminating Computer Science Inquiry and Communication', '["Apply data minimization, stakeholder, bias, fairness, accessibility, and professional-ethics reasoning to a bounded design.","Build a defensive threat model with proportionate controls, safe local tests, residual risks, and responsible escalation."]'::jsonb, '["Student Coursebook Lesson ICS4U-U5-L1: Privacy, Bias, Accessibility, and Ethical Decision Frameworks.","Complete the stakeholder-impact, unnecessary-data, and accessible-alternative map.","Student Coursebook Lesson ICS4U-U5-L2: Threat Modelling, Secure Design, and Responsible Disclosure.","Complete the asset-threat-control-residual-risk table without testing any real system."]'::jsonb, 'Remove unnecessary fictional fields, rewrite colour-only output as accessible text, build a defensive threat model, and explain why a control reduces but does not eliminate risk.', 'Scenario check on data minimization, bias evidence, accessibility acceptance criteria, threat modelling, authorization, and residual risk.', 'Unlock Module 10 after the impact map and defensive threat model are accepted. Teacher feedback checks evidence limits, accessibility, authorization, and residual risk.', 8, '8 h core lessons and embedded checks', 'Targeted response to the retrieval check or correction log, plus a discussion, office-hour, or message touchpoint.', 'Annotated readings, guided practice, knowledge-check corrections, and exit ticket.', 'published'),
  ('ics4u-m10', 'ICS4U', 10, 5, 'Environmental Evidence, Emerging Technology, and Capstone Defence', 'Culminating Computer Science Inquiry and Communication', '["Evaluate environmental, emerging-technology, research, and career claims using defined system boundaries and evidence limits.","Integrate modular design, algorithm analysis, testing, accessibility, security, privacy, environmental evidence, demonstration, and defence."]'::jsonb, '["Student Coursebook Lesson ICS4U-U5-L3: Environmental Stewardship, Emerging Technologies, Research, and Careers.","Complete the system-boundary, evidence-quality, and career/research question map.","Student Coursebook Lesson ICS4U-U5-L4: Capstone Integration, Demonstration, and Technical Defence.","Assessment Reading Library: Evidence File 5: Responsible Computing Impact Dossier.","Annotate the fictional brief, proposed data, threat and accessibility observations, environmental assumptions, capstone rubric, and defence requirements."]'::jsonb, 'Complete an integration trace from need to module to algorithm to test to risk control, rehearse a local demonstration, challenge one environmental claim, and answer a teacher-selected technical/ethical question.', 'Capstone-readiness review covering scope, fictional/public data, traceability, tests, accessibility, threat controls, environmental limitations, source record, and defence evidence.', 'Teacher checks technical and ethical evidence before the final defence. Unlock Module 11 after final submission, authenticated explanation, and a reflection on one unresolved limitation.', 10.5, '10.5 h lessons, application, assessment, and feedback', 'Rubric-linked process feedback, an authentication checkpoint or conference, and a documented unlock decision.', 'Evidence-file notes, staged assessment work, feedback record, final submission, and reflection or defence.', 'published'),
  ('ics4u-m11', 'ICS4U', 11, NULL, 'Cumulative Synthesis, Culminating Performance, and Mandatory Written Examination', 'Final Evaluation', '["Integrate programming, modular design, algorithm analysis, project evidence, and responsible-computing reasoning across unfamiliar cases.","Demonstrate independent, time-bounded code tracing, design analysis, evidence interpretation, and technical communication.","Complete and defend the existing culminating performance before the mandatory written examination."]'::jsonb, '["Review the five unit concept maps, test portfolios, and correction logs; identify one persistent misconception per unit.","Complete an interleaved set requiring code tracing, algorithm choice, modular design, test selection, and ethical/security analysis.","Complete one timed practice examination, analyse errors by category, and attend the required feedback conference.","Read the examination instructions, permitted materials, integrity requirements, and submission procedure."]'::jsonb, 'Use a five-station spiral review: trace and predict, design and decompose, analyse an algorithm, select verification evidence, and evaluate a responsible-computing scenario. Finish with a timed mock and teacher conference.', 'Exam-readiness checklist and timed mock examination; mock score is formative and does not replace the mandatory written examination.', 'The examination opens only after required coursework submissions and the exam-integrity check are complete, subject to documented accommodations. Final teacher feedback distinguishes concept, trace, design, evidence, and communication errors.', 3.5, '3.5 h final evaluation (2 h culminating performance + 1.5 h supervised written examination)', 'Culminating scope and source-trail checkpoints, authenticated individual defence, exam-readiness confirmation, approved accommodations, identity check, and supervised examination administration.', 'Culminating artefact, source/work history, checkpoint feedback, authenticated defence record, supervised examination script, and administration record.', 'published'),
  ('sph4u-m00', 'SPH4U', 0, NULL, 'Start Here: Learning Physics in the Lotus Platform', 'Course Orientation', '["Navigate the course, locate feedback and due dates, and explain the approved grade structure: 65% coursework, 25% mandatory written examination, 10% attendance and participation.","Establish ethical, safe, and traceable practices for diagrams, data, calculations, simulations, citations, and investigations."]'::jsonb, '["Read the course welcome, navigation guide, communication routines, and accessibility/support information.","Read the assessment overview, academic-integrity expectations, diagram/data conventions, and investigation safety boundaries.","Preview the five unit assessments and the SPH4U Mandatory Written Examination before beginning content."]'::jsonb, 'Complete a navigation scavenger hunt, submit a sample vector diagram and unit-checked calculation, and practise locating rubric feedback.', 'Ungraded prerequisite diagnostic covering Grade 11 mechanics, algebra, trigonometry, vectors, units, significant figures, and graph interpretation; students receive a targeted review list.', 'Teacher or automated feedback identifies prerequisite gaps. Unlock Module 1 after the navigation check and acknowledgement are complete; diagnostic score does not restrict entry.', 0, '1–2 h onboarding; not automatically recorded as credit time', 'Welcome message, diagnostic response, support routing, and navigation confirmation.', 'Navigation check, diagnostic record, and safety/integrity acknowledgement.', 'published'),
  ('sph4u-m01', 'SPH4U', 1, 1, 'Vector Kinematics and Forces in a Plane', 'Dynamics', '["Resolve and combine vector motion quantities in planar and projectile models.","Translate a physical situation into a free-body diagram and a consistent set of Newton-law equations."]'::jsonb, '["Student Coursebook Lesson SPH4U-U1-L1: Vector Kinematics and Projectile Models.","Complete the diagram-first vector and projectile retrieval set.","Student Coursebook Lesson SPH4U-U1-L2: Newton''s Laws for Motion in a Plane.","Complete one free-body-diagram-to-equations translation before opening the extensions."]'::jsonb, 'Complete a component-method vector set, compare analytic and simulated projectile results, and audit two flawed free-body diagrams before solving a planar force case.', 'Ten-item vector/kinematics/dynamics check requiring diagrams and units, followed by one correction attempt and an error-log entry.', 'Unlock Module 2 after both lesson checkpoints and one corrected free-body diagram are submitted. Teacher feedback targets coordinate choice, vector direction, and force identification.', 8, '8 h core lessons and embedded checks', 'Targeted response to the retrieval check or correction log, plus a discussion, office-hour, or message touchpoint.', 'Annotated readings, guided practice, knowledge-check corrections, and exit ticket.', 'published'),
  ('sph4u-m02', 'SPH4U', 2, 1, 'Circular Motion and Safety Decisions', 'Dynamics', '["Relate inward net force and acceleration to circular-motion variables without inventing an extra force.","Evaluate banked-curve or vertical-circle evidence and communicate a bounded safety recommendation."]'::jsonb, '["Student Coursebook Lesson SPH4U-U1-L3: Uniform Circular Motion.","Complete the inward-direction and net-force retrieval set.","Student Coursebook Lesson SPH4U-U1-L4: Banked Curves, Vertical Circles, and Safety Decisions.","Assessment Reading Library: Dynamics Design Evidence File.","Annotate the design constraints, assumptions, and safety criteria before calculating."]'::jsonb, 'Draw force diagrams at multiple positions, solve a banked-curve sensitivity case, and prepare a one-page safety rationale that separates calculation, assumption, and design margin.', 'Assessment-readiness quiz on radial direction, net force, normal force, friction, limiting cases, and safety-factor interpretation, followed by a rubric preflight.', 'Teacher verifies the force model and one sensitivity calculation before final submission. Unlock Module 3 after the assessment and a reflection on the most consequential assumption are complete.', 14, '14 h lessons, application, assessment, and feedback', 'Rubric-linked process feedback, an authentication checkpoint or conference, and a documented unlock decision.', 'Evidence-file notes, staged assessment work, feedback record, final submission, and reflection or defence.', 'published'),
  ('sph4u-m03', 'SPH4U', 3, 2, 'Work, Energy, Power, and Efficiency', 'Energy and Momentum', '["Use work-energy relationships and power to analyse motion and energy transfer.","Define system boundaries and distinguish total-energy conservation from mechanical-energy changes and efficiency losses."]'::jsonb, '["Student Coursebook Lesson SPH4U-U2-L1: Work, Kinetic Energy, and Power.","Complete the sign-of-work and work-energy retrieval set.","Student Coursebook Lesson SPH4U-U2-L2: Conservation of Energy and Efficiency.","Complete one energy-flow representation and reconcile it with the equation set."]'::jsonb, 'Audit a work-sign error, compare energy-flow and force-displacement solution paths, and calculate efficiency/power for a bounded device or motion case.', 'Mixed conceptual/calculation check on system boundary, work sign, energy transformation, power, and efficiency with mandatory corrections.', 'Unlock Module 4 after one complete energy-flow explanation and corrected calculation are submitted. Teacher feedback prioritizes boundary choice and conservation claims.', 8, '8 h core lessons and embedded checks', 'Targeted response to the retrieval check or correction log, plus a discussion, office-hour, or message touchpoint.', 'Annotated readings, guided practice, knowledge-check corrections, and exit ticket.', 'published'),
  ('sph4u-m04', 'SPH4U', 4, 2, 'Impulse, Momentum, and Collision Evidence', 'Energy and Momentum', '["Use impulse-momentum relationships and conservation with explicit system and direction conventions.","Resolve two-dimensional collision evidence and distinguish momentum conservation from kinetic-energy behaviour."]'::jsonb, '["Student Coursebook Lesson SPH4U-U2-L3: Impulse, Momentum, and One-Dimensional Collisions.","Complete the impulse-area and one-dimensional momentum checkpoint.","Student Coursebook Lesson SPH4U-U2-L4: Two-Dimensional Momentum and Collision Evidence.","Assessment Reading Library: Collision Protection Evidence File.","Annotate measurement uncertainty, comparison basis, and protection criteria before analysis."]'::jsonb, 'Complete impulse-from-graph calculations, solve a two-dimensional collision with component checks, and compare two protection designs using force-time and energy evidence.', 'Assessment-readiness check on system choice, signs/components, impulse, momentum conservation, energy loss, uncertainty, and claim strength.', 'Teacher verifies component conservation and one uncertainty statement before final submission. Unlock Module 5 after the assessment and feedback-use reflection are complete.', 14, '14 h lessons, application, assessment, and feedback', 'Rubric-linked process feedback, an authentication checkpoint or conference, and a documented unlock decision.', 'Evidence-file notes, staged assessment work, feedback record, final submission, and reflection or defence.', 'published'),
  ('sph4u-m05', 'SPH4U', 5, 3, 'Gravitational and Electric Fields', 'Gravitational, Electric, and Magnetic Fields', '["Use field and potential models for gravitational interactions and orbital systems.","Represent electric field, potential, work, and capacitor behaviour with consistent sign and symmetry reasoning."]'::jsonb, '["Student Coursebook Lesson SPH4U-U3-L1: Gravitational Fields, Potential, and Orbits.","Complete the field-versus-potential and orbit retrieval set.","Student Coursebook Lesson SPH4U-U3-L2: Electric Fields, Potential, and Capacitors.","Complete a field/equipotential translation and one capacitor calculation."]'::jsonb, 'Compare field and potential representations, solve an orbit/energy case, map a multi-charge arrangement, and justify a capacitor or field-model choice from stated assumptions.', 'Diagram-and-calculation check on inverse-square relationships, potential, field direction, energy, equipotentials, and capacitors; require corrections.', 'Unlock Module 6 after a complete field/potential comparison and correction log are submitted. Teacher feedback targets scalar/vector distinctions and sign/symmetry reasoning.', 8, '8 h core lessons and embedded checks', 'Targeted response to the retrieval check or correction log, plus a discussion, office-hour, or message touchpoint.', 'Annotated readings, guided practice, knowledge-check corrections, and exit ticket.', 'published'),
  ('sph4u-m06', 'SPH4U', 6, 3, 'Magnetic Forces, Induction, and Field Technologies', 'Gravitational, Electric, and Magnetic Fields', '["Determine the magnitude and direction of magnetic forces on charges and currents.","Use flux change, Faraday''s law, and Lenz''s law to analyse technologies and compare field-based options."]'::jsonb, '["Student Coursebook Lesson SPH4U-U3-L3: Magnetic Forces on Charges and Currents.","Complete the right-hand-rule and magnitude checkpoint.","Student Coursebook Lesson SPH4U-U3-L4: Electromagnetic Induction and Field Technologies.","Assessment Reading Library: Field Technology Evidence File.","Annotate performance, evidence quality, safety, uncertainty, and comparison criteria before drafting."]'::jsonb, 'Complete direction card sorts, calculate magnetic force/flux cases, explain two Lenz-law signs, and compare field technologies on a normalized performance-risk basis.', 'Assessment-readiness check on force direction, flux, induced emf sign, energy conservation, evidence sufficiency, and technology trade-offs.', 'Teacher verifies direction reasoning and one quantitative comparison before final submission. Unlock Module 7 after the assessment and revision record are complete.', 14, '14 h lessons, application, assessment, and feedback', 'Rubric-linked process feedback, an authentication checkpoint or conference, and a documented unlock decision.', 'Evidence-file notes, staged assessment work, feedback record, final submission, and reflection or defence.', 'published'),
  ('sph4u-m07', 'SPH4U', 7, 4, 'Wavefronts, Superposition, and Interference', 'The Wave Nature of Light', '["Represent wavefronts, phase, and superposition using diagrams and equations.","Use path difference and double-slit evidence to predict and interpret interference patterns."]'::jsonb, '["Student Coursebook Lesson SPH4U-U4-L1: Wavefronts, Phase, and Superposition.","Complete the phase/path-difference prediction set.","Student Coursebook Lesson SPH4U-U4-L2: Double-Slit Interference.","Complete one diagram-to-equation double-slit example and a limiting-case check."]'::jsonb, 'Annotate wavefront and phase diagrams, predict pattern changes before calculating, and reconcile a simulated fringe spacing with the double-slit relation.', 'Concept-and-calculation check on phase, path difference, constructive/destructive conditions, fringe spacing, and pattern scaling, with corrections.', 'Unlock Module 8 after the pattern prediction and corrected calculation are complete. Teacher feedback targets diagram-equation consistency and proportional reasoning.', 8, '8 h core lessons and embedded checks', 'Targeted response to the retrieval check or correction log, plus a discussion, office-hour, or message touchpoint.', 'Annotated readings, guided practice, knowledge-check corrections, and exit ticket.', 'published'),
  ('sph4u-m08', 'SPH4U', 8, 4, 'Diffraction, Resolution, Refraction, and Polarization', 'The Wave Nature of Light', '["Analyse diffraction, gratings, and resolution using pattern evidence and appropriate approximations.","Use refraction, total internal reflection, and polarization to justify an optical communication/design decision."]'::jsonb, '["Student Coursebook Lesson SPH4U-U4-L3: Diffraction, Gratings, and Resolution.","Complete the diffraction/grating pattern-comparison checkpoint.","Student Coursebook Lesson SPH4U-U4-L4: Refraction, Total Internal Reflection, and Polarization.","Assessment Reading Library: Optical System Evidence File.","Annotate wavelength, geometry, resolution, loss, and design constraints before selecting a system."]'::jsonb, 'Compare slit/grating patterns, calculate one resolution and one critical-angle case, and use a decision matrix to select an optical design while stating model limits.', 'Assessment-readiness check on pattern variables, resolution, Snell''s law, total internal reflection, polarization, units, and evidence-based design trade-offs.', 'Teacher verifies one pattern/resolution calculation and the connection between evidence and design criterion. Unlock Module 9 after the final brief and limitation reflection are submitted.', 14, '14 h lessons, application, assessment, and feedback', 'Rubric-linked process feedback, an authentication checkpoint or conference, and a documented unlock decision.', 'Evidence-file notes, staged assessment work, feedback record, final submission, and reflection or defence.', 'published'),
  ('sph4u-m09', 'SPH4U', 9, 5, 'Photons, Matter Waves, and Quantum Evidence', 'Revolutions in Modern Physics: Quantum Mechanics and Special Relativity', '["Use photoelectric evidence to distinguish the roles of frequency and intensity and evaluate classical/quantum models.","Use de Broglie and diffraction evidence to explain matter waves and the limits of classical descriptions."]'::jsonb, '["Student Coursebook Lesson SPH4U-U5-L1: Photons and the Photoelectric Effect.","Complete the classical-versus-photon prediction table.","Student Coursebook Lesson SPH4U-U5-L2: Matter Waves, Electron Diffraction, and Uncertainty.","Complete one photon-energy and one de Broglie calculation with an evidence interpretation."]'::jsonb, 'Interpret photoelectric graphs, solve photon and matter-wave cases, and create a claim-evidence-reasoning table explaining why one classical prediction fails.', 'Quantum-evidence check on photon energy, stopping potential, threshold frequency, de Broglie wavelength, uncertainty, and model claims, followed by corrections.', 'Unlock Module 10 after the model-comparison table and corrected quantitative check are complete. Teacher feedback distinguishes observation, inference, and model claim.', 8, '8 h core lessons and embedded checks', 'Targeted response to the retrieval check or correction log, plus a discussion, office-hour, or message touchpoint.', 'Annotated readings, guided practice, knowledge-check corrections, and exit ticket.', 'published'),
  ('sph4u-m10', 'SPH4U', 10, 5, 'Relativity, Mass-Energy, and Modern Technology', 'Revolutions in Modern Physics: Quantum Mechanics and Special Relativity', '["Apply constant-light-speed and relativity principles to time, length, and simultaneity evidence.","Use mass-energy and model-change evidence to evaluate a modern-physics technology claim."]'::jsonb, '["Student Coursebook Lesson SPH4U-U5-L3: Special Relativity: Time, Length, and Simultaneity.","Complete a two-frame event diagram before calculating Lorentz effects.","Student Coursebook Lesson SPH4U-U5-L4: Mass-Energy, Model Change, and Modern Technologies.","Assessment Reading Library: Modern Physics Evidence File.","Annotate the evidence hierarchy, model limits, uncertainty, and technology implications before drafting."]'::jsonb, 'Complete two-frame event diagrams, solve time-dilation/length/mass-energy cases with limiting checks, and rank evidence supporting a modern-technology claim.', 'Assessment-readiness check on frames, invariants, simultaneity, Lorentz factor, mass-energy, evidence hierarchy, uncertainty, and model limits.', 'Teacher verifies the reference-frame model and distinction between evidence and inference. Unlock Module 11 after the assessment and feedback-use reflection are complete.', 11.5, '11.5 h lessons, application, assessment, and feedback', 'Rubric-linked process feedback, an authentication checkpoint or conference, and a documented unlock decision.', 'Evidence-file notes, staged assessment work, feedback record, final submission, and reflection or defence.', 'published'),
  ('sph4u-m11', 'SPH4U', 11, NULL, 'Cumulative Synthesis and Mandatory Written Examination', 'Final Evaluation', '["Select and connect force, energy, momentum, field, wave, and modern-physics models across unfamiliar contexts.","Demonstrate independent, time-bounded diagramming, calculation, checking, and evidence communication."]'::jsonb, '["Review the five unit concept maps and correction logs; identify one persistent misconception per unit.","Complete an interleaved problem set that requires system/model selection and a diagram before calculation.","Complete one timed practice examination, analyse errors by category, and attend the required feedback conference.","Read the examination instructions, permitted materials, integrity requirements, and submission procedure."]'::jsonb, 'Use a five-station spiral review: draw the system, identify the governing model, solve, check units/limits, interpret evidence, and revise. Finish with a timed mock and teacher conference based on the error log.', 'Exam-readiness checklist and timed mock examination; mock score is formative and does not replace the mandatory written examination.', 'The examination opens only after required coursework submissions and the exam-integrity check are complete, subject to documented accommodations. Final teacher feedback distinguishes model selection, diagram, physics, calculation, and communication errors.', 2.5, '2.5 h supervised written examination', 'Readiness confirmation, approved accommodations, identity check, supervision, and post-exam closure.', 'Supervised examination script and administration record.', 'published'),
  ('mhf4u-m00', 'MHF4U', 0, NULL, 'Start Here: Learning Advanced Functions in the Lotus Platform', 'Course Orientation', '["Navigate the course, locate feedback and due dates, and explain the approved grade structure: 65% coursework, 25% mandatory written examination, 10% attendance and participation.","Establish traceable practices for algebraic work, graphing-tool use, source citation, and mathematical communication."]'::jsonb, '["Read the course welcome, navigation guide, communication routines, and accessibility/support information.","Read the assessment overview, academic-integrity expectations, calculator and graphing-tool rules, and notation standards.","Preview the five unit assessments and the MHF4U Mandatory Written Examination before beginning content."]'::jsonb, 'Complete a navigation scavenger hunt, submit a sample algebra-and-graph record, and practise locating rubric feedback and resubmission instructions.', 'Ungraded prerequisite diagnostic covering algebra, factoring, function notation, transformations, domain and range, exact values, and graph interpretation; students receive a targeted review list.', 'Teacher or automated feedback identifies prerequisite gaps. Unlock Module 1 after the navigation check and acknowledgement are complete; diagnostic score does not restrict entry.', 0, '1–2 h onboarding; not automatically recorded as credit time', 'Welcome message, diagnostic response, support routing, and navigation confirmation.', 'Navigation check, diagnostic record, and safety/integrity acknowledgement.', 'published'),
  ('mhf4u-m01', 'MHF4U', 1, 1, 'Exponential Structure, Inverses, and Logarithmic Laws', 'Exponential and Logarithmic Functions', '["Connect exponential parameters, transformations, inverses, and graphical features.","Use the definition and laws of logarithms with stated domains and reversible algebraic steps."]'::jsonb, '["Student Coursebook Lesson MHF4U-U1-L1: Exponential Functions, Parameters, and Inverses.","Complete the parameter-effect and inverse-function retrieval set.","Student Coursebook Lesson MHF4U-U1-L2: Logarithms and the Laws of Logarithms.","Complete the logarithm-law error sort before opening the external resources."]'::jsonb, 'Match equations, tables, and graphs; derive inverse pairs; expand and condense logarithms; and explain every domain restriction before using a graphing tool to verify.', 'Short mixed-representation check on parameter effects, inverse relationships, logarithmic laws, and domain restrictions, with one correction attempt.', 'Unlock Module 2 after both lesson checkpoints and a corrected logarithm-law item are submitted. Teacher feedback targets reversible reasoning and domain control.', 8, '8 h core lessons and embedded checks', 'Targeted response to the retrieval check or correction log, plus a discussion, office-hour, or message touchpoint.', 'Annotated readings, guided practice, knowledge-check corrections, and exit ticket.', 'published'),
  ('mhf4u-m02', 'MHF4U', 2, 1, 'Equations, Growth and Decay, and Model Limits', 'Exponential and Logarithmic Functions', '["Solve exponential and logarithmic equations while checking domains and extraneous values.","Build, compare, and critique growth or decay models using units, assumptions, residual evidence, and meaningful thresholds."]'::jsonb, '["Student Coursebook Lesson MHF4U-U1-L3: Solving Exponential and Logarithmic Equations.","Complete the equation-method decision tree and verify each solution in the original equation.","Student Coursebook Lesson MHF4U-U1-L4: Growth, Decay, Scales, and Model Limits.","Assessment Reading Library: Evidence File 1: Growth, Decay, and Threshold Model Casebook.","Annotate variables, units, assumptions, thresholds, and required model comparisons before drafting."]'::jsonb, 'Solve and verify a mixed equation set, estimate parameters from bounded data, compare residual patterns, and write a conditional recommendation that identifies when the selected model stops being credible.', 'Assessment-readiness check on equation methods, domains, units, parameter meaning, residuals, thresholds, and extrapolation limits, followed by a rubric self-check.', 'Teacher verifies one equation pathway, one parameter interpretation, and one model limitation before final submission. Unlock Module 3 after the assessment and feedback-use reflection are complete.', 14, '14 h lessons, application, assessment, and feedback', 'Rubric-linked process feedback, an authentication checkpoint or conference, and a documented unlock decision.', 'Evidence-file notes, staged assessment work, feedback record, final submission, and reflection or defence.', 'published'),
  ('mhf4u-m03', 'MHF4U', 3, 2, 'Radians, Exact Values, and Periodic Models', 'Trigonometric Functions', '["Use radian measure and the unit circle to derive exact trigonometric values.","Connect parameters, transformations, reciprocal relationships, and context in periodic models."]'::jsonb, '["Student Coursebook Lesson MHF4U-U2-L1: Radians, the Unit Circle, and Exact Values.","Complete the unit-circle retrieval grid without a calculator, then correct sign and reference-angle errors.","Student Coursebook Lesson MHF4U-U2-L2: Sinusoidal and Reciprocal Function Models.","Complete a parameter-to-feature table before using graphing resources."]'::jsonb, 'Derive exact values, convert between angle measures, match periodic equations to graphs, and critique a sinusoidal model whose scale or phase interpretation is incorrect.', 'Mixed exact-value, reciprocal-function, transformation, and contextual-parameter check with an annotated correction for each missed item.', 'Unlock Module 4 after students submit a complete unit-circle grid and one verified periodic model. Teacher flags degree-radian, sign, and parameter-meaning misconceptions.', 8, '8 h core lessons and embedded checks', 'Targeted response to the retrieval check or correction log, plus a discussion, office-hour, or message touchpoint.', 'Annotated readings, guided practice, knowledge-check corrections, and exit ticket.', 'published'),
  ('mhf4u-m04', 'MHF4U', 4, 2, 'Identities, Equations, and Periodic Design Decisions', 'Trigonometric Functions', '["Prove trigonometric identities through logically valid one-sided transformations.","Solve trigonometric equations on stated domains and use solutions in a constrained design decision."]'::jsonb, '["Student Coursebook Lesson MHF4U-U2-L3: Trigonometric Identities and Proof.","Complete the identity strategy sort and annotate every legal transformation.","Student Coursebook Lesson MHF4U-U2-L4: Solving Trigonometric Equations.","Assessment Reading Library: Evidence File 2: Periodic Systems Design Packet.","Annotate the design interval, units, constraints, required proof, and equation evidence before drafting."]'::jsonb, 'Audit a circular identity proof, solve an equation on two different intervals, fit a periodic model to the evidence packet, and test whether the resulting design satisfies all stated constraints.', 'Assessment-readiness check on identity logic, equivalent transformations, general versus interval solutions, periodic parameters, and constraint verification.', 'Teacher checks one identity proof, one full interval solution, and the design-constraint test before final submission. Unlock Module 5 after the assessment and reflection are complete.', 14, '14 h lessons, application, assessment, and feedback', 'Rubric-linked process feedback, an authentication checkpoint or conference, and a documented unlock decision.', 'Evidence-file notes, staged assessment work, feedback record, final submission, and reflection or defence.', 'published'),
  ('mhf4u-m05', 'MHF4U', 5, 3, 'Polynomial Structure, Zeros, and Algebraic Theorems', 'Polynomial and Rational Functions', '["Connect degree, leading coefficient, multiplicity, zeros, and end behaviour across representations.","Use division and polynomial theorems to factor, solve, verify, and interpret equations."]'::jsonb, '["Student Coursebook Lesson MHF4U-U3-L1: Polynomial Structure, Zeros, and End Behaviour.","Complete a graph-to-factor and factor-to-graph retrieval set.","Student Coursebook Lesson MHF4U-U3-L2: Polynomial Division, Theorems, and Equations.","Complete one problem by both synthetic or long division and direct substitution verification."]'::jsonb, 'Construct polynomials from constraints, rank plausible graphs, perform division, apply the remainder and factor theorems, and reconcile algebraic roots with numerical graph evidence.', 'Short check on polynomial structure, multiplicity, end behaviour, division, and theorem use; require one independent verification method.', 'Unlock Module 6 after a polynomial is reconstructed and verified from a bounded set of constraints. Teacher feedback targets multiplicity, sign, and theorem interpretation.', 8, '8 h core lessons and embedded checks', 'Targeted response to the retrieval check or correction log, plus a discussion, office-hour, or message touchpoint.', 'Annotated readings, guided practice, knowledge-check corrections, and exit ticket.', 'published'),
  ('mhf4u-m06', 'MHF4U', 6, 3, 'Rational Behaviour, Inequalities, and Constraint Analysis', 'Polynomial and Rational Functions', '["Distinguish restrictions, removable discontinuities, vertical or horizontal asymptotes, and intercepts.","Solve polynomial and rational inequalities using critical values, sign analysis, and contextual constraints."]'::jsonb, '["Student Coursebook Lesson MHF4U-U3-L3: Rational Functions, Restrictions, Holes, and Asymptotes.","Complete a feature-classification table and preserve every original restriction.","Student Coursebook Lesson MHF4U-U3-L4: Polynomial and Rational Inequalities.","Assessment Reading Library: Evidence File 3: Function Behaviour and Constraint Case.","Annotate excluded values, boundary conditions, decision intervals, and required representations before drafting."]'::jsonb, 'Audit a cancelled factor that hides a restriction, build a sign chart from exact critical values, compare algebraic and graphical solution sets, and defend the feasible interval in the evidence case.', 'Assessment-readiness check on restrictions, holes, asymptotes, sign intervals, endpoint inclusion, and contextual feasibility, followed by a rubric self-check.', 'Teacher verifies original-domain restrictions, critical values, and one independent representation before final submission. Unlock Module 7 after the assessment and reflection are complete.', 14, '14 h lessons, application, assessment, and feedback', 'Rubric-linked process feedback, an authentication checkpoint or conference, and a documented unlock decision.', 'Evidence-file notes, staged assessment work, feedback record, final submission, and reflection or defence.', 'published'),
  ('mhf4u-m07', 'MHF4U', 7, 4, 'Function Operations, Domains, and Inverse Control', 'Characteristics of Functions', '["Perform operations and compositions while determining the resulting domain from all constraints.","Construct, verify, and interpret inverse functions using appropriate restricted domains."]'::jsonb, '["Student Coursebook Lesson MHF4U-U4-L1: Operations on Functions and Domain Intersections.","Complete a domain-intersection and composition-order retrieval set.","Student Coursebook Lesson MHF4U-U4-L2: Inverse Functions and Restricted Domains.","Complete an inverse-verification table using composition and graph symmetry."]'::jsonb, 'Build operation and composition tables, compare f composed with g against g composed with f, restrict a non-one-to-one function, and verify the inverse algebraically and graphically.', 'Short check on operation domains, composition order, one-to-one conditions, restricted domains, and inverse verification with corrections.', 'Unlock Module 8 after one composition and one inverse are verified with correct domains. Teacher feedback prioritizes domain provenance and equivalence.', 8, '8 h core lessons and embedded checks', 'Targeted response to the retrieval check or correction log, plus a discussion, office-hour, or message touchpoint.', 'Annotated readings, guided practice, knowledge-check corrections, and exit ticket.', 'published'),
  ('mhf4u-m08', 'MHF4U', 8, 4, 'Rates of Change, Function Comparison, and Numerical Decisions', 'Characteristics of Functions', '["Estimate and interpret average or instantaneous rate of change from tables, graphs, and equations.","Compare function families and use transparent numerical methods to support a bounded decision."]'::jsonb, '["Student Coursebook Lesson MHF4U-U4-L3: Average and Instantaneous Rate of Change.","Complete a secant-to-tangent table and interpret units in context.","Student Coursebook Lesson MHF4U-U4-L4: Comparing Functions and Numerical Solutions.","Assessment Reading Library: Evidence File 4: Function Pipeline and Rate Audit.","Annotate domain intersections, rate intervals, numerical tolerances, and verification requirements before assembling the portfolio."]'::jsonb, 'Estimate rates at decreasing intervals, compare two candidate functions on a shared domain, implement a transparent numerical search, and audit whether the resulting recommendation is sensitive to tolerance or rounding.', 'Assessment-readiness check on rate units, interval choice, domain intersection, graphical/numerical agreement, tolerance, and reasonableness.', 'Teacher checks one rate calculation, one domain intersection, and one numerical-verification record before final submission. Unlock Module 9 after the portfolio and reflection are complete.', 14, '14 h lessons, application, assessment, and feedback', 'Rubric-linked process feedback, an authentication checkpoint or conference, and a documented unlock decision.', 'Evidence-file notes, staged assessment work, feedback record, final submission, and reflection or defence.', 'published'),
  ('mhf4u-m09', 'MHF4U', 9, 5, 'Model Selection, Evidence, and Sensitivity', 'Culminating Advanced Functions Inquiry and Communication', '["Select a defensible function family from context, data provenance, behaviour, and assumptions.","Estimate parameters, analyse residuals, and test sensitivity before claiming that a model supports a decision."]'::jsonb, '["Student Coursebook Lesson MHF4U-U5-L1: Model Selection, Assumptions, and Data Provenance.","Complete a model-family screening matrix and a data-provenance check.","Student Coursebook Lesson MHF4U-U5-L2: Parameter Estimation, Residuals, and Sensitivity.","Complete one residual and one sensitivity analysis before selecting the dossier model."]'::jsonb, 'Screen candidate models, trace every data value to its source, estimate parameters, graph residuals, perturb a key assumption, and write a provisional claim with an explicit limitation.', 'Model-readiness conference artifact covering provenance, units, domain, parameter meaning, residual pattern, sensitivity, and uncertainty.', 'Unlock Module 10 after the proposed model, source record, residual evidence, and revision plan are accepted. Teacher feedback targets model sufficiency rather than visual fit alone.', 8, '8 h core lessons and embedded checks', 'Targeted response to the retrieval check or correction log, plus a discussion, office-hour, or message touchpoint.', 'Annotated readings, guided practice, knowledge-check corrections, and exit ticket.', 'published'),
  ('mhf4u-m10', 'MHF4U', 10, 5, 'Multi-Representation Argument, Verification, and Defence', 'Culminating Advanced Functions Inquiry and Communication', '["Build a coherent decision argument across algebraic, graphical, numerical, and contextual representations.","Diagnose errors, verify key results independently, communicate limitations, and defend the final recommendation."]'::jsonb, '["Student Coursebook Lesson MHF4U-U5-L3: Multi-Representation Argument and Verification.","Complete the representation-consistency audit and independent verification record.","Student Coursebook Lesson MHF4U-U5-L4: Synthesis, Error Diagnosis, and Examination Readiness.","Assessment Reading Library: Evidence File 5: Multi-Model Decision Dossier.","Annotate decision criteria, competing models, required evidence, uncertainty, and defence prompts before final synthesis."]'::jsonb, 'Assemble the claim-evidence-reasoning chain, cross-check a key result by a second method, stress-test the recommendation under one changed assumption, and rehearse a bounded mathematical defence.', 'Assessment-readiness review on model selection, representation consistency, verification, sensitivity, source use, and defence responses.', 'Teacher verifies model provenance, one independent check, and one limitation before final submission. Unlock Module 11 after the dossier, defence, and feedback-use reflection are complete.', 11.5, '11.5 h lessons, application, assessment, and feedback', 'Rubric-linked process feedback, an authentication checkpoint or conference, and a documented unlock decision.', 'Evidence-file notes, staged assessment work, feedback record, final submission, and reflection or defence.', 'published'),
  ('mhf4u-m11', 'MHF4U', 11, NULL, 'Cumulative Synthesis and Mandatory Written Examination', 'Final Evaluation', '["Integrate exponential, logarithmic, trigonometric, polynomial, rational, inverse, and rate-of-change reasoning across unfamiliar contexts.","Demonstrate independent, time-bounded algebraic, graphical, numerical, and written mathematical communication."]'::jsonb, '["Review the five unit concept maps and correction logs; identify one persistent misconception per unit.","Complete an interleaved problem set that requires function-family and method selection before calculation.","Complete one timed practice examination, analyse errors by category, and attend the required feedback conference.","Read the examination instructions, permitted materials, integrity requirements, and submission procedure."]'::jsonb, 'Use a five-station spiral review: identify the function family and constraints, choose a method, solve, verify in a second representation, interpret, and revise. Finish with a timed mock and teacher conference based on the error log.', 'Exam-readiness checklist and timed mock examination; mock score is formative and does not replace the mandatory written examination.', 'The examination opens only after required coursework submissions and the exam-integrity check are complete, subject to documented accommodations. Final teacher feedback distinguishes model selection, algebra, representation, interpretation, and communication errors.', 2.5, '2.5 h supervised written examination', 'Readiness confirmation, approved accommodations, identity check, supervision, and post-exam closure.', 'Supervised examination script and administration record.', 'published'),
  ('mcv4u-m00', 'MCV4U', 0, NULL, 'Start Here: Learning Calculus and Vectors in the Lotus Platform', 'Course Orientation', '["Navigate the course, locate feedback and due dates, and explain the approved grade structure: 65% coursework, 25% mandatory written examination, 10% attendance and participation.","Establish traceable practices for algebra, notation, diagrams, graphing-tool use, source citation, and mathematical verification."]'::jsonb, '["Read the course welcome, navigation guide, communication routines, and accessibility/support information.","Read the assessment overview, academic-integrity expectations, calculator and graphing-tool rules, and notation standards.","Preview the five unit assessments and the MCV4U Mandatory Written Examination before beginning content."]'::jsonb, 'Complete a navigation scavenger hunt, submit a sample derivative-and-vector solution record, and practise locating rubric feedback and resubmission instructions.', 'Ungraded prerequisite diagnostic covering advanced functions, algebra, transformations, trigonometry, function notation, coordinate geometry, and vector basics; students receive a targeted review list.', 'Teacher or automated feedback identifies prerequisite gaps. Unlock Module 1 after the navigation check and acknowledgement are complete; diagnostic score does not restrict entry.', 0, '1–2 h onboarding; not automatically recorded as credit time', 'Welcome message, diagnostic response, support routing, and navigation confirmation.', 'Navigation check, diagnostic record, and safety/integrity acknowledgement.', 'published'),
  ('mcv4u-m01', 'MCV4U', 1, 1, 'Secants, Limits, and Instantaneous Change', 'Rate of Change', '["Calculate and interpret average rate of change as a secant slope with meaningful units.","Use limits of difference quotients to connect secants, tangents, and instantaneous rate of change."]'::jsonb, '["Student Coursebook Lesson MCV4U-U1-L1: Average Rate of Change and Secant Slopes.","Complete the secant-slope retrieval set and interpret every rate in context.","Student Coursebook Lesson MCV4U-U1-L2: Limits, Tangent Slopes, and Instantaneous Change.","Complete a shrinking-interval table and difference-quotient reconstruction before opening the external resources."]'::jsonb, 'Compute secant slopes from equations, tables, and graphs; build a shrinking-interval record; derive one tangent slope from first principles; and explain units and assumptions.', 'Short mixed-representation check on secants, difference quotients, limits, tangent slopes, and contextual units with one correction attempt.', 'Unlock Module 2 after both lesson checkpoints and one corrected difference-quotient solution are submitted. Teacher feedback targets notation, interval logic, and interpretation.', 8, '8 h core lessons and embedded checks', 'Targeted response to the retrieval check or correction log, plus a discussion, office-hour, or message touchpoint.', 'Annotated readings, guided practice, knowledge-check corrections, and exit ticket.', 'published'),
  ('mcv4u-m02', 'MCV4U', 2, 1, 'Derivative Graphs, Rules, and Evidence', 'Rate of Change', '["Connect a function and its derivative through slopes, signs, critical inputs, and graphical behaviour.","Apply and verify derivative rules for core function families and simple combinations."]'::jsonb, '["Student Coursebook Lesson MCV4U-U1-L3: Derivative Graphs and Function Behaviour.","Complete a function-to-derivative graph matching task with sign justifications.","Student Coursebook Lesson MCV4U-U1-L4: Derivative Rules for Core Function Families.","Assessment Reading Library: Evidence File 1: Secant, Tangent, and Derivative Records.","Annotate variables, units, estimation intervals, derivative evidence, and required verification before drafting."]'::jsonb, 'Match function and derivative records, differentiate by rule and first principles where required, verify a derivative numerically or graphically, and interpret one rate in the evidence context.', 'Assessment-readiness check on derivative graphs, core rules, notation, units, and independent verification, followed by a rubric self-check.', 'Teacher verifies one limit or derivative pathway, one graphical connection, and one contextual interpretation before final submission. Unlock Module 3 after the assessment and feedback-use reflection are complete.', 14, '14 h lessons, application, assessment, and feedback', 'Rubric-linked process feedback, an authentication checkpoint or conference, and a documented unlock decision.', 'Evidence-file notes, staged assessment work, feedback record, final submission, and reflection or defence.', 'published'),
  ('mcv4u-m03', 'MCV4U', 3, 2, 'Curve Analysis and Constrained Optimization', 'Derivatives and Their Applications', '["Use first and second derivatives to analyse intervals, extrema, concavity, inflection, and curve shape.","Build and solve constrained optimization models, then verify feasibility and global conclusions."]'::jsonb, '["Student Coursebook Lesson MCV4U-U2-L1: First and Second Derivatives in Curve Sketching.","Complete the derivative-sign and concavity retrieval table before sketching.","Student Coursebook Lesson MCV4U-U2-L2: Optimization with Defined Constraints.","Complete the variable-constraint-objective checklist and endpoint verification for one model."]'::jsonb, 'Build a sign chart, sketch a curve from derivative evidence, translate a bounded situation into an objective and domain, locate critical and endpoint candidates, and interpret the optimum conditionally.', 'Mixed short-answer check on critical inputs, derivative signs, concavity, feasible domains, candidate testing, and contextual interpretation.', 'Unlock Module 4 after one curve-analysis record and one fully constrained optimization model are accepted. Teacher feedback flags endpoint, domain, and global-versus-local errors.', 8, '8 h core lessons and embedded checks', 'Targeted response to the retrieval check or correction log, plus a discussion, office-hour, or message touchpoint.', 'Annotated readings, guided practice, knowledge-check corrections, and exit ticket.', 'published'),
  ('mcv4u-m04', 'MCV4U', 4, 2, 'Motion, Related Rates, and Model-Based Decisions', 'Derivatives and Their Applications', '["Connect position, velocity, acceleration, rest, direction, and displacement through derivative evidence.","Use marginal or related rates in bounded decisions while maintaining units, assumptions, and model limits."]'::jsonb, '["Student Coursebook Lesson MCV4U-U2-L3: Motion, Velocity, and Acceleration Models.","Complete a motion-state table from symbolic and graphical evidence.","Student Coursebook Lesson MCV4U-U2-L4: Rates and Model-Based Decision Problems.","Assessment Reading Library: Evidence File 2: Optimization, Motion, and Marginal Decisions.","Annotate constraints, units, rate definitions, decision criteria, and required verification before assembling the portfolio."]'::jsonb, 'Analyse a complete motion interval, distinguish speed from velocity, solve a rate or marginal decision with units, compare candidate actions, and test one result against original constraints.', 'Assessment-readiness check on derivative relationships, motion signs, optimization, marginal interpretation, units, constraints, and reasonableness.', 'Teacher checks one derivative sign analysis, one constrained optimum, and one rate interpretation before final submission. Unlock Module 5 after the portfolio and reflection are complete.', 14, '14 h lessons, application, assessment, and feedback', 'Rubric-linked process feedback, an authentication checkpoint or conference, and a documented unlock decision.', 'Evidence-file notes, staged assessment work, feedback record, final submission, and reflection or defence.', 'published'),
  ('mcv4u-m05', 'MCV4U', 5, 3, 'Vectors, Components, and Linear Combinations', 'Geometry and Algebra of Vectors', '["Represent vectors geometrically and algebraically in two-space and three-space with defined coordinate conventions.","Perform vector operations and linear combinations to model displacement, force, and other directed quantities."]'::jsonb, '["Student Coursebook Lesson MCV4U-U3-L1: Vectors in Two-Space and Three-Space.","Complete a representation-conversion and magnitude retrieval set.","Student Coursebook Lesson MCV4U-U3-L2: Vector Operations and Linear Combinations.","Complete a component audit with labelled axes, units, and resultant checks."]'::jsonb, 'Convert points and directed segments to vectors, normalize vectors, resolve and combine components, and verify a resultant graphically and algebraically under stated coordinate conventions.', 'Short check on notation, components, magnitude, unit vectors, scalar multiplication, addition, and contextual interpretation with corrections.', 'Unlock Module 6 after one two-space and one three-space model are verified. Teacher feedback targets orientation, components, units, and geometric-algebraic consistency.', 8, '8 h core lessons and embedded checks', 'Targeted response to the retrieval check or correction log, plus a discussion, office-hour, or message touchpoint.', 'Annotated readings, guided practice, knowledge-check corrections, and exit ticket.', 'published'),
  ('mcv4u-m06', 'MCV4U', 6, 3, 'Dot Products, Cross Products, and Spatial Decisions', 'Geometry and Algebra of Vectors', '["Use dot products to determine angles, perpendicularity, scalar projections, and context-specific components.","Use cross products to determine orientation, normals, area, and torque while explaining order and units."]'::jsonb, '["Student Coursebook Lesson MCV4U-U3-L3: Dot Product, Angles, and Projections.","Complete a projection diagram and angle calculation with an independent reasonableness check.","Student Coursebook Lesson MCV4U-U3-L4: Cross Product, Normals, Area, and Torque.","Assessment Reading Library: Evidence File 3: Vector Components, Products, and Orientation.","Annotate axes, units, orientation rules, operation choices, and required visual evidence before drafting."]'::jsonb, 'Choose between dot and cross products from the question meaning, calculate and verify angle/projection/normal/area results, test orientation by order reversal, and explain one real-world decision.', 'Assessment-readiness check on product choice, angles, projections, perpendicularity, orientation, normals, area or torque, units, and visual verification.', 'Teacher verifies one operation choice, one product calculation, and one geometric interpretation before final submission. Unlock Module 7 after the case file and reflection are complete.', 14, '14 h lessons, application, assessment, and feedback', 'Rubric-linked process feedback, an authentication checkpoint or conference, and a documented unlock decision.', 'Evidence-file notes, staged assessment work, feedback record, final submission, and reflection or defence.', 'published'),
  ('mcv4u-m07', 'MCV4U', 7, 4, 'Representing Lines and Planes in Three-Space', 'Integrated Calculus and Vectors Applications', '["Construct and interpret vector and parametric equations of lines from points, directions, and context.","Construct and convert scalar or vector equations of planes from points, directions, and normals."]'::jsonb, '["Student Coursebook Lesson MCV4U-U4-L1: Vector and Parametric Equations of Lines.","Complete a data-to-line and line-to-data retrieval set.","Student Coursebook Lesson MCV4U-U4-L2: Scalar and Vector Equations of Planes.","Complete a plane-representation conversion table and verify point membership."]'::jsonb, 'Construct lines and planes from multiple data forms, convert between equations, test membership, identify non-unique representations of the same object, and verify results with a labelled 3D view.', 'Short check on line directions, plane normals, parameters, conversions, point membership, and geometric interpretation with corrections.', 'Unlock Module 8 after one line and one plane are represented and independently verified. Teacher feedback prioritizes direction/normal logic and parameter meaning.', 8, '8 h core lessons and embedded checks', 'Targeted response to the retrieval check or correction log, plus a discussion, office-hour, or message touchpoint.', 'Annotated readings, guided practice, knowledge-check corrections, and exit ticket.', 'published'),
  ('mcv4u-m08', 'MCV4U', 8, 4, 'Intersections, Configurations, Distances, and Angles', 'Integrated Calculus and Vectors Applications', '["Classify and solve intersections or configurations of lines and planes using algebraic and geometric evidence.","Calculate distances and angles in three-space and use them in a bounded spatial decision."]'::jsonb, '["Student Coursebook Lesson MCV4U-U4-L3: Intersections and Configurations of Lines and Planes.","Complete the configuration decision tree and verify one intersection in all original equations.","Student Coursebook Lesson MCV4U-U4-L4: Distances and Angles in Three-Space.","Assessment Reading Library: Evidence File 4: Line, Plane, Distance, and Boundary Cases.","Annotate coordinate conventions, constraints, boundary cases, tolerances, and required verifications before drafting."]'::jsonb, 'Solve and classify line/plane systems, test substituted points, calculate a distance and angle with normalized formulas, visualize boundary cases, and defend the feasible spatial option.', 'Assessment-readiness check on configurations, system consistency, intersections, distance formulas, angles, tolerances, and boundary interpretation.', 'Teacher verifies one classification, one substituted intersection or distance, and one boundary/tolerance statement before final submission. Unlock Module 9 after the assessment and reflection are complete.', 14, '14 h lessons, application, assessment, and feedback', 'Rubric-linked process feedback, an authentication checkpoint or conference, and a documented unlock decision.', 'Evidence-file notes, staged assessment work, feedback record, final submission, and reflection or defence.', 'published'),
  ('mcv4u-m09', 'MCV4U', 9, 5, 'Calculus and Vector Model Selection', 'Culminating Calculus and Vectors Inquiry and Communication', '["Select and justify a calculus model using variables, domains, units, derivative evidence, and decision constraints.","Construct a compatible vector model with explicit origin, axes, orientation, parameters, forces, paths, or boundaries."]'::jsonb, '["Student Coursebook Lesson MCV4U-U5-L1: Calculus Model Selection and Evidence.","Complete a calculus-model screening and source-provenance record.","Student Coursebook Lesson MCV4U-U5-L2: Vector Modelling of Paths, Forces, and Constraints.","Complete a coordinate-frame and compatibility audit before combining the models."]'::jsonb, 'Screen candidate calculus and vector models, trace all input data, define a compatible coordinate and parameter system, test units and domains, and write a provisional integrated claim with a limitation.', 'Model-readiness conference artifact covering source provenance, variables, units, domains, coordinate frame, parameter scale, constraints, and verification plan.', 'Unlock Module 10 after the calculus model, vector model, source record, compatibility audit, and revision plan are accepted. Teacher feedback targets model sufficiency and cross-model consistency.', 8, '8 h core lessons and embedded checks', 'Targeted response to the retrieval check or correction log, plus a discussion, office-hour, or message touchpoint.', 'Annotated readings, guided practice, knowledge-check corrections, and exit ticket.', 'published'),
  ('mcv4u-m10', 'MCV4U', 10, 5, 'Integrated Decision Study, Error Diagnosis, and Defence', 'Culminating Calculus and Vectors Inquiry and Communication', '["Integrate calculus and vector evidence into a bounded decision without losing domain, unit, coordinate, or parameter meaning.","Diagnose errors, verify decisive results independently, communicate uncertainty, and defend the final recommendation."]'::jsonb, '["Student Coursebook Lesson MCV4U-U5-L3: Integrated Calculus and Vector Decision Study.","Complete the cross-model substitution, units, and constraint audit.","Student Coursebook Lesson MCV4U-U5-L4: Synthesis, Error Diagnosis, and Mathematical Defence.","Assessment Reading Library: Evidence File 5: Integrated Model, Sensitivity, and Defence.","Annotate decision criteria, model interfaces, sensitivity variables, evidence limits, and defence prompts before final synthesis."]'::jsonb, 'Assemble the integrated claim-evidence-reasoning chain, verify one derivative and one spatial result by independent methods, change one sensitive assumption, and rehearse a bounded mathematical defence.', 'Assessment-readiness review on model compatibility, calculus and vector calculations, units, coordinate conventions, sensitivity, source use, and defence responses.', 'Teacher verifies model compatibility, one independent calculus check, one independent vector check, and one limitation before final submission. Unlock Module 11 after the dossier, defence, and feedback-use reflection are complete.', 11.5, '11.5 h lessons, application, assessment, and feedback', 'Rubric-linked process feedback, an authentication checkpoint or conference, and a documented unlock decision.', 'Evidence-file notes, staged assessment work, feedback record, final submission, and reflection or defence.', 'published'),
  ('mcv4u-m11', 'MCV4U', 11, NULL, 'Cumulative Synthesis and Mandatory Written Examination', 'Final Evaluation', '["Integrate rate-of-change, derivative-application, vector-operation, and three-space reasoning across unfamiliar contexts.","Demonstrate independent, time-bounded algebraic, graphical, diagrammatic, numerical, and written mathematical communication."]'::jsonb, '["Review the five unit concept maps and correction logs; identify one persistent misconception per unit.","Complete an interleaved problem set that requires model, representation, and method selection before calculation.","Complete one timed practice examination, analyse errors by category, and attend the required feedback conference.","Read the examination instructions, permitted materials, integrity requirements, and submission procedure."]'::jsonb, 'Use a five-station spiral review: identify the governing model and coordinate frame, choose a method, solve, verify in a second representation, interpret, and revise. Finish with a timed mock and teacher conference based on the error log.', 'Exam-readiness checklist and timed mock examination; mock score is formative and does not replace the mandatory written examination.', 'The examination opens only after required coursework submissions and the exam-integrity check are complete, subject to documented accommodations. Final teacher feedback distinguishes model selection, calculus, vectors, representation, interpretation, and communication errors.', 2.5, '2.5 h supervised written examination', 'Readiness confirmation, approved accommodations, identity check, supervision, and post-exam closure.', 'Supervised examination script and administration record.', 'published'),
  ('bbb4m-m00', 'BBB4M', 0, NULL, 'Start Here: Learning International Business in the Lotus Platform', 'Course Orientation', '["Navigate the course, locate feedback and due dates, and explain the approved grade structure: 65% coursework, 10% culminating performance and defence, 15% mandatory written examination, 10% attendance and participation.","Distinguish stable fictional assessment evidence, current official context, textbook concepts, calculations, assumptions, and student recommendations."]'::jsonb, '["Read the course welcome, navigation guide, communication routines, and accessibility/support information.","Read the assessment overview, academic-integrity expectations, source-evaluation rules, and the required labels for evidence status, assumptions, and limitations.","Preview the five unit assessments and the BBB4M Mandatory Written Examination before beginning content.","Preview BBB4M Culminating Performance and Defence and its staged authenticated defence checkpoints."]'::jsonb, 'Complete a navigation scavenger hunt, classify a short set of claims as fictional case data, current official context, concept, calculation, assumption, or decision, and practise finding rubric feedback.', 'Ungraded prerequisite diagnostic covering business vocabulary, percentages, exchange-rate reasoning, charts, source status, claim-evidence-reasoning, and stakeholder analysis; students receive a targeted review list.', 'Teacher or automated feedback identifies prerequisite gaps. Unlock Module 1 after the navigation check and acknowledgement are complete; diagnostic score does not restrict entry.', 0, '1–2 h onboarding; not automatically recorded as credit time', 'Welcome message, diagnostic response, support routing, and navigation confirmation.', 'Navigation check, diagnostic record, and safety/integrity acknowledgement.', 'published'),
  ('bbb4m-m01', 'BBB4M', 1, 1, 'International Business Language and Comparative Advantage', 'Business, Trade, and the Economy', '["Use international-business vocabulary and evidence labels precisely in a bounded decision.","Calculate opportunity cost and use comparative advantage without confusing it with absolute advantage or a complete policy recommendation."]'::jsonb, '["Student Coursebook Lesson BBB4M-U1-L1: International Business Vocabulary and Evidence-Based Communication.","Complete the terminology and evidence-status table, including scope and limitation columns.","Student Coursebook Lesson BBB4M-U1-L2: Specialization, Comparative Advantage, and Opportunity Cost.","Complete the two-economy opportunity-cost calculation and explain what the model can and cannot decide."]'::jsonb, 'Classify business claims by evidence status, calculate opportunity costs for two fictional economies, identify comparative advantage, and write a conditional trade claim with a stakeholder and limitation.', 'Vocabulary, evidence-status, and comparative-advantage check with one correction attempt and a short explanation of the model boundary.', 'Unlock Module 2 after the terminology/evidence table and corrected opportunity-cost analysis are submitted. Teacher feedback targets evidence status, units, and overclaiming.', 8, '8 h core lessons and embedded checks', 'Targeted response to the retrieval check or correction log, plus a discussion, office-hour, or message touchpoint.', 'Annotated readings, guided practice, knowledge-check corrections, and exit ticket.', 'published'),
  ('bbb4m-m02', 'BBB4M', 2, 1, 'Trade Flows, Value Chains, and Interdependence Decisions', 'Business, Trade, and the Economy', '["Interpret trade-flow, balance, investment, ownership, period, currency, and domestic-value-added evidence without collapsing distinct measures.","Map global value-chain dependencies and compare export or assembly choices using control, employment, stakeholder, and risk evidence."]'::jsonb, '["Student Coursebook Lesson BBB4M-U1-L3: Trade Flows, Balance, Foreign Investment, and Canada''s Economy.","Complete the trade-and-investment flow ledger with direction, period, currency, and ownership labels.","Student Coursebook Lesson BBB4M-U1-L4: Interdependence, Global Value Chains, and Trade Institutions.","Assessment Reading Library: Evidence File 1: NorthStar Cycle Components Trade-and-Interdependence Case.","Annotate the decision, stable fictional evidence, current-context needs, alternatives, responsible-business constraints, and rubric before drafting."]'::jsonb, 'Build a value-chain map, compare direct export, distributor export, licensed assembly, and pause using common criteria, run one adverse scenario, and submit a conditional recommendation for feedback.', 'Assessment-readiness check on trade-flow labels, value-chain dependencies, tariff assumptions, alternatives, stakeholder effects, and monitoring triggers, followed by a rubric self-check.', 'Teacher gives rubric-linked feedback on the alternative comparison and evidence status. Unlock Module 3 after final submission and a reflection naming one material uncertainty.', 12, '12 h lessons, application, assessment, and feedback', 'Rubric-linked process feedback, an authentication checkpoint or conference, and a documented unlock decision.', 'Evidence-file notes, staged assessment work, feedback record, final submission, and reflection or defence.', 'published'),
  ('bbb4m-m03', 'BBB4M', 3, 2, 'Globalization, Institutions, Infrastructure, and Capability', 'The Global Business Environment', '["Connect globalization drivers to specific firm choices, stakeholder effects, opportunities, risks, and responses.","Interpret infrastructure, institution, and human-capability indicators through an explicit business mechanism and evidence limitation."]'::jsonb, '["Student Coursebook Lesson BBB4M-U2-L1: Globalization and the Strategic Choices of Canadian Firms.","Complete the driver-impact matrix for a fictional Canadian firm.","Student Coursebook Lesson BBB4M-U2-L2: Country Participation: Infrastructure, Institutions, and Human Capability.","Complete the participation-systems map and identify where a country indicator cannot predict one firm''s outcome."]'::jsonb, 'Link three globalization drivers to operational decisions, audit indicator metadata, and create a country-participation map that shows mechanism, affected stage, constraint, mitigation, and uncertainty.', 'Indicator-literacy and globalization check requiring source metadata, mechanism, stakeholder effect, and one limitation for every conclusion.', 'Unlock Module 4 after the driver-impact and indicator-mechanism maps are accepted. Teacher feedback flags missing metadata, ecological inference, and unsupported country rankings.', 8, '8 h core lessons and embedded checks', 'Targeted response to the retrieval check or correction log, plus a discussion, office-hour, or message touchpoint.', 'Annotated readings, guided practice, knowledge-check corrections, and exit ticket.', 'published'),
  ('bbb4m-m04', 'BBB4M', 4, 2, 'Economic Scenarios, Exchange Rates, and Market Screening', 'The Global Business Environment', '["Translate economic indicators and exchange-rate scenarios into bounded revenue, cost, timing, and risk effects.","Use official trade and institutional gateways to compare markets while preserving scope, current-context, and responsible-business limitations."]'::jsonb, '["Student Coursebook Lesson BBB4M-U2-L3: Economic Indicators, Exchange Rates, and Business-Cycle Scenarios.","Complete the indicator-and-cash-flow table and base/adverse exchange-rate scenario.","Student Coursebook Lesson BBB4M-U2-L4: Trade Agreements, Institutions, and Current Global Trends.","Assessment Reading Library: Evidence File 2: PolarPeak Foods Market-Screen Case.","Annotate the two-market evidence, criteria, weights, feasibility constraints, sensitivity test, and responsible-business controls."]'::jsonb, 'Build a transparent two-market screen, convert one exchange-rate scenario into margin effects, apply a disqualifying condition, and test whether a reasonable change in weight or assumption reverses the ranking.', 'Assessment-readiness check on indicator definitions, units, exchange-rate direction, criteria, sensitivity, feasibility, official-source status, and monitoring triggers.', 'Teacher checks the exchange-rate direction, criteria definitions, and sensitivity logic before final submission. Unlock Module 5 after the assessment and an uncertainty statement are submitted.', 14, '14 h lessons, application, assessment, and feedback', 'Rubric-linked process feedback, an authentication checkpoint or conference, and a documented unlock decision.', 'Evidence-file notes, staged assessment work, feedback record, final submission, and reflection or defence.', 'published'),
  ('bbb4m-m05', 'BBB4M', 5, 3, 'Culture, Communication, Political Risk, and Legal Evidence', 'Factors Influencing International Success', '["Use cultural inquiry and consultation to design testable adaptations without treating national labels as fixed individual traits.","Trace political, legal, and regulatory evidence from authority and jurisdiction to a specific operational requirement, owner, and escalation trigger."]'::jsonb, '["Student Coursebook Lesson BBB4M-U3-L1: Culture, Communication, and Evidence-Based Adaptation.","Complete the communication-and-adaptation map with evidence source, consultation step, risk, and test.","Student Coursebook Lesson BBB4M-U3-L2: Political, Legal, and Regulatory Environments.","Complete the rule-to-operation register and mark every point that requires current local or professional advice."]'::jsonb, 'Audit a stereotyped adaptation claim, design a consultation and testing step, trace one rule to an operational control, and write a conditional recommendation with a legal-advice flag.', 'Scenario check on cultural evidence, adaptation testing, jurisdiction, authority, operational ownership, responsible-business impact, and advice limits.', 'Unlock Module 6 after the adaptation map and rule register are accepted. Teacher feedback distinguishes inquiry from stereotype and official information from legal advice.', 8, '8 h core lessons and embedded checks', 'Targeted response to the retrieval check or correction log, plus a discussion, office-hour, or message touchpoint.', 'Annotated readings, guided practice, knowledge-check corrections, and exit ticket.', 'published'),
  ('bbb4m-m06', 'BBB4M', 6, 3, 'Geography, Infrastructure, Competitiveness, and Risk Review', 'Factors Influencing International Success', '["Connect affordability, geography, climate, infrastructure, connectivity, and service conditions to specific user and operating mechanisms.","Build a transparent country screen and test how changed weights, scores, assumptions, and feasibility constraints affect the decision."]'::jsonb, '["Student Coursebook Lesson BBB4M-U3-L3: Economic, Geographic, and Infrastructure Conditions.","Complete the site-to-service map with segment, route, lead time, climate, connectivity, maintenance, and uncertainty.","Student Coursebook Lesson BBB4M-U3-L4: Competitiveness, Common Entry Mistakes, and Transparent Country Screening.","Assessment Reading Library: Evidence File 3: Lumen Learning Devices Success-Factors Case.","Annotate the market/adaptation decision, cultural and legal limits, weighted screen, feasibility controls, sensitivity test, and missing evidence."]'::jsonb, 'Map route and service constraints, build a weighted country screen, run one adverse case and one weight/score sensitivity, apply a responsible-business disqualifier, and compare the result with an unweighted narrative.', 'Assessment-readiness quiz on mechanism, country indicators, score rules, sensitivity, feasibility, stereotype avoidance, and monitoring triggers, followed by a rubric self-audit.', 'Teacher checks indicator mechanisms, cultural limits, and sensitivity logic before final submission. Unlock Module 7 after the assessment and an evidence-gap reflection.', 14, '14 h lessons, application, assessment, and feedback', 'Rubric-linked process feedback, an authentication checkpoint or conference, and a documented unlock decision.', 'Evidence-file notes, staged assessment work, feedback record, final submission, and reflection or defence.', 'published'),
  ('bbb4m-m07', 'BBB4M', 7, 4, 'International Research, Segmentation, and Adaptation', 'International Marketing and Distribution', '["Design fit-for-purpose international research that links method, sample, measure, segment implication, bias risk, and follow-up.","Compare standardization and adaptation choices using customer, legal, evidence, cost, brand, accessibility, and test criteria."]'::jsonb, '["Student Coursebook Lesson BBB4M-U4-L1: International Market Research, Segmentation, and Targeting.","Complete the research-evidence matrix and identify one sampling or interpretation risk.","Student Coursebook Lesson BBB4M-U4-L2: Product Adaptation, Positioning, Branding, and Promotion.","Complete the adaptation decision table and design one bounded message or feature test."]'::jsonb, 'Convert a broad market claim into a research question, compare secondary and bounded primary evidence, define a reachable segment, and test one product or message adaptation for accessibility and unsupported claims.', 'Research-and-adaptation check requiring a defensible method, sample limitation, segment evidence, adaptation criterion, accessibility test, and revision.', 'Unlock Module 8 after the research and adaptation tables pass review. Teacher feedback flags imaginary average customers, weak samples, unsupported claims, and inaccessible promotion.', 8, '8 h core lessons and embedded checks', 'Targeted response to the retrieval check or correction log, plus a discussion, office-hour, or message touchpoint.', 'Annotated readings, guided practice, knowledge-check corrections, and exit ticket.', 'published'),
  ('bbb4m-m08', 'BBB4M', 8, 4, 'Pricing, Currency, Channels, and Border-Ready Distribution', 'International Marketing and Distribution', '["Build a transparent landed-cost and channel-economics waterfall with exchange-rate, fee, return, timing, price, and margin assumptions.","Map order-to-return logistics, documents, inventory states, handoffs, controls, service promises, and exception routes."]'::jsonb, '["Student Coursebook Lesson BBB4M-U4-L3: International Pricing, Currency, Payment, and Channel Economics.","Complete the unit-economics waterfall and one currency or return-rate sensitivity.","Student Coursebook Lesson BBB4M-U4-L4: Distribution, Logistics, Inventory, and Border-Ready Service.","Assessment Reading Library: Evidence File 4: CedarWave Skin Care Launch-Plan Case.","Annotate the segment, adaptation, price, currency, channel, distribution controls, adverse scenarios, and pause conditions before drafting the launch plan."]'::jsonb, 'Calculate total delivered cost and margin, run delay/demand-spike/damage/return scenarios through the process, verify each handoff and document owner, and submit a conditional launch or pause recommendation.', 'Assessment-readiness review of currency direction, landed cost, margin, channel incentives, documents, inventory states, exception routes, claims, accessibility, and service integrity.', 'Teacher checks the cost waterfall and operational handoffs before final submission. Unlock Module 9 after the assessment and a service-risk reflection are complete.', 14, '14 h lessons, application, assessment, and feedback', 'Rubric-linked process feedback, an authentication checkpoint or conference, and a documented unlock decision.', 'Evidence-file notes, staged assessment work, feedback record, final submission, and reflection or defence.', 'published'),
  ('bbb4m-m09', 'BBB4M', 9, 5, 'Ethics, Labour Standards, and Worker-Centred Due Diligence', 'Ethics, Operations, and Market-Entry Plan', '["Identify actual and potential impacts, business relationships, leverage, prevention, mitigation, tracking, communication, escalation, and remedy.","Evaluate working conditions using worker-centred evidence while distinguishing international standards, national law, management claims, and verification gaps."]'::jsonb, '["Student Coursebook Lesson BBB4M-U5-L1: Ethical Decision-Making and Responsible Business Conduct.","Complete the due-diligence register with stakeholder, severity, likelihood, leverage, control, owner, evidence, and remedy.","Student Coursebook Lesson BBB4M-U5-L2: Working Conditions, Labour Standards, and Cross-Cultural Teams.","Complete the worker-centred conditions table and identify the evidence required to verify each management claim."]'::jsonb, 'Map a fictional labour impact to cause, contribution, or direct linkage, compare prevention and mitigation options, design worker-centred verification, and specify an escalation and remedy route.', 'Scenario check on stakeholder impact, severity, leverage, standards versus law, worker evidence, corrective action, tracking, communication, and remedy.', 'Unlock Module 10 after the due-diligence and worker-evidence records are accepted. Teacher feedback checks stakeholder voice, evidence gaps, law/standard distinctions, and remedy.', 8, '8 h core lessons and embedded checks', 'Targeted response to the retrieval check or correction log, plus a discussion, office-hour, or message touchpoint.', 'Annotated readings, guided practice, knowledge-check corrections, and exit ticket.', 'published'),
  ('bbb4m-m10', 'BBB4M', 10, 5, 'Border Compliance, Entry Modes, and Integrated Implementation', 'Ethics, Operations, and Market-Entry Plan', '["Build a preliminary shipment-readiness register while marking classification, origin, permit, valuation, documentation, and professional-advice limits.","Compare entry modes and a phased implementation using governance rights, costs, milestones, metrics, risk owners, evidence gates, and stop triggers."]'::jsonb, '["Student Coursebook Lesson BBB4M-U5-L3: Border Compliance, Documentation, and Supply-Chain Controls.","Complete the shipment-readiness register and place a hold on every unresolved material compliance item.","Student Coursebook Lesson BBB4M-U5-L4: Entry Modes, Integrated Implementation, and Decision Defence.","Assessment Reading Library: Evidence File 5: Boreal Mobility Systems Integrated Entry Case.","Annotate the ethics, labour, border, operations, finance, governance, stakeholder, risk, stage-gate, and pause evidence before drafting."]'::jsonb, 'Audit a fictional shipment record, compare entry modes with consistent criteria, change key weights and assumptions, check unresolved high risks, and require evidence at each stage gate before further commitment.', 'Capstone-readiness review of classification/origin assumptions, document ownership, entry-mode control, financial and operating feasibility, due diligence, stage gates, metrics, and stop triggers.', 'Teacher checks unresolved high risks and evidence gates before final submission. Unlock Module 11 after the recommendation, authenticated defence, and one monitoring-trigger reflection are complete.', 12.5, '12.5 h lessons, application, assessment, and feedback', 'Rubric-linked process feedback, an authentication checkpoint or conference, and a documented unlock decision.', 'Evidence-file notes, staged assessment work, feedback record, final submission, and reflection or defence.', 'published'),
  ('bbb4m-m11', 'BBB4M', 11, NULL, 'Cumulative Synthesis, Culminating Performance, and Mandatory Written Examination', 'Final Evaluation', '["Integrate trade, global-environment, success-factor, marketing, distribution, ethics, operations, and entry-mode reasoning across unfamiliar cases.","Demonstrate independent, time-bounded evidence interpretation, calculation, alternative comparison, risk analysis, and business communication.","Complete and defend the existing culminating performance before the mandatory written examination."]'::jsonb, '["Review the five unit concept maps, decision matrices, and correction logs; identify one persistent misconception per unit.","Complete an interleaved case set requiring evidence-status labels, calculations, stakeholder analysis, alternative comparison, sensitivity, and a monitoring trigger.","Complete one timed practice examination, analyse errors by category, and attend the required feedback conference.","Read the examination instructions, permitted materials, integrity requirements, and submission procedure."]'::jsonb, 'Use a five-station spiral review: classify evidence, calculate and check units, compare markets or modes, analyse stakeholders and risks, and defend a conditional recommendation. Finish with a timed mock and teacher conference.', 'Exam-readiness checklist and timed mock examination; mock score is formative and does not replace the mandatory written examination.', 'The examination opens only after required coursework submissions and the exam-integrity check are complete, subject to documented accommodations. Final teacher feedback distinguishes concept, evidence, calculation, decision, and communication errors.', 3.5, '3.5 h final evaluation (2 h culminating performance + 1.5 h supervised written examination)', 'Culminating scope and source-trail checkpoints, authenticated individual defence, exam-readiness confirmation, approved accommodations, identity check, and supervised examination administration.', 'Culminating artefact, source/work history, checkpoint feedback, authenticated defence record, supervised examination script, and administration record.', 'published')
