  ('sch4u-m01-resource-01', 'sch4u-m01', 1, 'Brief Guide to the Nomenclature of Organic Chemistry', 'International Union of Pure and Applied Chemistry (IUPAC)', 'external_url', 'https://iupac.org/wp-content/uploads/2021/06/Organic-Brief-Guide-brochure_v1.1_June2021.pdf', NULL, 'Convert the naming sequence into a one-page decision tree and test it on teacher-selected structures.', 'student', 'published'),
